    function injectUniversalBack(content,pathname,fallback="/"){
      if(pathname==="/"||pathname.startsWith("/menu/"))return content;
      if(content.includes('id="okyUniversalBack"'))return content;
      const safeFallback=String(fallback||"/").startsWith("/")?String(fallback):"/";
      const ui=`<style id="oky-back-style">#okyUniversalBack{position:fixed;left:max(10px,env(safe-area-inset-left));top:max(68px,calc(env(safe-area-inset-top) + 58px));z-index:8000;min-width:44px;min-height:44px;border:1px solid #b9cfdd;border-radius:999px;background:#fff;color:#062542;padding:9px 13px;font:900 13px Arial;box-shadow:0 6px 18px #001a2e2b;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}@media(max-width:700px){#okyUniversalBack{top:max(62px,calc(env(safe-area-inset-top) + 54px))}}@media print{#okyUniversalBack{display:none!important}}</style><a id="okyUniversalBack" href="${safeFallback}" aria-label="Önceki sayfaya dön">← Geri</a><script id="oky-back-script">(()=>{const b=document.getElementById('okyUniversalBack');if(!b)return;b.onclick=e=>{try{const r=document.referrer?new URL(document.referrer):null;if(r&&r.origin===location.origin&&history.length>1){e.preventDefault();history.back();return}}catch(_){}};})();</script>`;
      return content.replace("</body>",ui+"</body>");
    }

