      const savedJS=`<script id="member-saved-script">(()=>{const saved=document.getElementById('memberSaved'),grid=document.querySelector('.memberDashboard .grid'),planner=document.getElementById('memberPlanner'),nav=document.querySelector('.memberQuickNav');if(!saved||!grid||!nav)return;const tabs=document.createElement('div');tabs.className='memberTabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','İşletme çalışma alanı');const home=document.createElement('button'),list=document.createElement('button');home.type=list.type='button';home.id='memberHomeTab';list.id='memberSavedTab';home.textContent='Çalışma Alanım';list.textContent='KAYDEDİLENLER';[home,list].forEach(b=>{b.setAttribute('role','tab');tabs.appendChild(b)});grid.id='memberHomePanel';grid.setAttribute('role','tabpanel');grid.setAttribute('aria-labelledby',home.id);home.setAttribute('aria-controls',grid.id);list.setAttribute('aria-controls',saved.id);nav.after(tabs);let loaded=false,busy=false;const activate=isSaved=>{saved.hidden=!isSaved;grid.hidden=isSaved;if(planner)planner.hidden=isSaved;home.setAttribute('aria-selected',String(!isSaved));list.setAttribute('aria-selected',String(isSaved));home.tabIndex=isSaved?-1:0;list.tabIndex=isSaved?0:-1;if(isSaved&&!loaded)refresh()};home.onclick=()=>activate(false);list.onclick=()=>activate(true);tabs.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const isSaved=e.key==='End'||(e.key!=='Home'&&document.activeElement===home);activate(isSaved);(isSaved?list:home).focus()}});async function read(url){const r=await fetch(url,{cache:'no-store',headers:{accept:'application/json'}});let j;try{j=await r.json()}catch(_){throw Error('Sunucu kayıtları okunamadı. Yeniden deneyin.')}if(!r.ok||!j.ok)throw Error(r.status===401?'Oturumunuz sona erdi. Yeniden giriş yapın.':r.status===403?'Bu kayıtlara erişim yetkiniz bulunmuyor.':'Kayıtlar şu anda yüklenemiyor. Yeniden deneyin.');return j}const text=(tag,value)=>{const n=document.createElement(tag);n.textContent=String(value||'');return n};function entries(box,records,kind){box.textContent='';if(!Array.isArray(records))throw Error('Kayıt listesi doğrulanamadı.');if(!records.length){box.textContent='Bu işletme hesabında henüz kayıt yok.';return}records.forEach(record=>{const row=document.createElement('div');row.className='savedEntry';const info=document.createElement('div');info.appendChild(text('b',record.title||'İsimsiz kayıt'));info.appendChild(text('small',kind==='recipe'?String(record.servings||'')+' porsiyon · '+(record.status==='active'?'Kayıtlı reçete':'Taslak'):String(record.record_type||'COST')));row.appendChild(info);if(kind==='recipe'){const link=document.createElement('a');link.href='/kolay-recete?recipe='+encodeURIComponent(record.id);link.textContent='Aç / Devam Et →';row.appendChild(link)}else{const resume=document.createElement('a');resume.href='/cost?record='+encodeURIComponent(record.id);resume.textContent='Aç / Devam Et →';row.appendChild(resume);const button=document.createElement('button');button.type='button';button.textContent='Kayıt Özeti';button.onclick=()=>{let detail=row.querySelector('.savedDetail');if(detail){detail.hidden=!detail.hidden;return}detail=document.createElement('pre');detail.className='savedDetail';detail.style.gridColumn='1 / -1';let p;try{p=typeof record.payload==='string'?JSON.parse(record.payload):record.payload}catch(_){p=null}detail.textContent=p?JSON.stringify(p,null,2):'Kayıt içeriği okunamadı.';row.appendChild(detail);const link=document.createElement('a');link.href='/cost';link.textContent='COST Çalışma Alanını Aç →';row.appendChild(link)};row.appendChild(button)}box.appendChild(row)})}function renderDeviceGroups(){const scope=String(window.OKY_BUSINESS_SCOPE||'').trim(),costs=document.getElementById('memberDeviceCosts'),menu=document.getElementById('memberDeviceMenu'),academy=document.getElementById('memberDeviceAcademy'),agenda=document.getElementById('memberDeviceAgenda');if(!costs||!menu||!academy||!agenda)return;[costs,menu,academy,agenda].forEach(box=>box.textContent='');if(!scope){[costs,menu,academy,agenda].forEach(box=>box.textContent='İşletme oturumu doğrulanamadı. Cihaz kayıtları açılmadı.');return}const suffix=':business:'+scope,academyPrefix='okyAcademyBiz:v1:'+encodeURIComponent(scope)+':',agendaPrefix='okyAgenda:'+${JSON.stringify(String((me&&me.business_id)||'')+':'+String((me&&me.user_id)||''))}+':';const readDevice=key=>{const raw=localStorage.getItem(key);if(!raw)return null;return JSON.parse(raw)},entry=(box,title,description,route)=>{const row=document.createElement('div');row.className='savedEntry';const info=document.createElement('div');info.appendChild(text('b',title));if(description)info.appendChild(text('small',description));row.appendChild(info);const link=document.createElement('a');link.href=route;link.textContent='Modülde Aç →';row.appendChild(link);box.appendChild(row)};try{[['okyanusCostRecords','Hesap sonuçları','/cost?tab=p9'],['okyanusCostIngredients','Malzeme kütüphanesi','/cost?tab=p1'],['okyanusCostPreps','Hazırlık reçeteleri','/cost?tab=p2'],['okyanusFixedPeriods','Sabit gider dönemleri','/cost?tab=p4'],['okyanusBusinessMonths','İşletme ayları','/cost?tab=p7']].forEach(([key,title,route])=>{const value=readDevice(key+suffix);if(!value)return;if(Array.isArray(value)){value.slice(0,250).forEach((record,index)=>{if(record&&typeof record==='object')entry(costs,title+' · '+String(record.summary||record.name||record.month||record.type||index+1),record.date||'',route)})}else if(typeof value==='object')Object.keys(value).slice(0,250).forEach(period=>entry(costs,title+' · '+period,'',route))});if(!costs.children.length)costs.textContent='Bu işletme için bu cihazda COST kaydı yok.'}catch(_){costs.textContent='COST cihaz kayıtları okunamadı. Tarayıcı depolamasını kontrol edin.'}try{const draft=readDevice('okyanusDigitalMenuV1'+suffix);if(draft&&typeof draft==='object'&&!Array.isArray(draft))entry(menu,draft.menuName||'Menü taslağı',(Array.isArray(draft.items)?draft.items.length:0)+' ürün','/dijital-menu');else menu.textContent='Bu işletme için bu cihazda menü taslağı yok.'}catch(_){menu.textContent='Menü cihaz taslağı okunamadı.'}try{const progress=readDevice(academyPrefix+'okyanusAcademyProgress'),check=readDevice(academyPrefix+'okyanusAcademyCheck'),lab=readDevice(academyPrefix+'okyanusAcademyLastLab'),last=readDevice(academyPrefix+'okyanusAcademyLast');if(progress&&typeof progress==='object'&&!Array.isArray(progress))entry(academy,'Eğitim ilerlemesi',Object.keys(progress).length+' konu kaydı','/akademi');if(check&&typeof check==='object')entry(academy,'İşletme kontrolü','Kayıtlı kontrol çalışması','/akademi');if(lab&&typeof lab==='object')entry(academy,lab.name||'Son laboratuvar çalışması',lab.result||'','/akademi');if(Array.isArray(last))entry(academy,'Son eğitim konusu','Kayıtlı son konu','/akademi');if(!academy.children.length)academy.textContent='Bu işletme için bu cihazda Akademi kaydı yok.'}catch(_){academy.textContent='Akademi cihaz kayıtları okunamadı.'}try{const keys=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key&&key.startsWith(agendaPrefix))keys.push(key)}keys.sort().reverse().slice(0,90).forEach(key=>{const note=localStorage.getItem(key);if(note)entry(agenda,key.slice(agendaPrefix.length),String(note).slice(0,180),'/benim-okyanusum')});if(!agenda.children.length)agenda.textContent='Bu işletme ve kullanıcı için bu cihazda ajanda notu yok.'}catch(_){agenda.textContent='Ajanda cihaz kayıtları okunamadı.'}}
    async function refresh(){if(busy)return;busy=true;renderDeviceGroups();const button=document.getElementById('refreshMemberSaved');button.disabled=true;const recipes=document.getElementById('memberSavedRecipes'),costs=document.getElementById('memberSavedCosts'),menus=document.getElementById('memberSavedMenus');recipes.textContent=costs.textContent=menus.textContent='Kayıtlar yükleniyor…';await Promise.all([read('/api/member/recipes').then(j=>entries(recipes,j.recipes,'recipe')).catch(e=>recipes.textContent=e.message),read('/api/cost/records').then(j=>entries(costs,j.records,'cost')).catch(e=>costs.textContent=e.message),read('/api/member/digital-menus').then(j=>{menus.textContent='';if(!Array.isArray(j.menus))throw Error('Menü listesi doğrulanamadı.');if(!j.menus.length)menus.textContent='Bu işletme hesabında henüz yayınlanmış menü yok.';j.menus.forEach(menu=>{const row=document.createElement('div');row.className='savedEntry';row.appendChild(text('b',menu.title||'Dijital Menü'));const link=document.createElement('a');link.href=menu.editToken?'/dijital-menu?menu='+encodeURIComponent(menu.menuId||menu.id):'/menu/'+encodeURIComponent(menu.menuId||menu.id);link.textContent=menu.editToken?'Aç / Devam Et →':'Yayınlanmış Menüyü Aç →';row.appendChild(link);menus.appendChild(row)})}).catch(e=>menus.textContent=e.message)]);loaded=true;busy=false;button.disabled=false}document.getElementById('refreshMemberSaved').onclick=refresh;activate(false)})();</script>`;
