    function replaceHomeDigitalMenuShowcase(base,replacement){
      const marker='<section class="digitalMenuHero"';
      const start=base.indexOf(marker);
      if(start<0){
        console.error('VITRINE_TARGET_NOT_FOUND');
        return base;
      }
      const end=base.indexOf('</section>',start);
      if(end<0){
        console.error('VITRINE_TARGET_END_NOT_FOUND');
        return base;
      }
      return base.slice(0,start)+replacement+base.slice(end+'</section>'.length);
    }

    function vitrineSectionHTML(row,p){
      const scenes=Array.isArray(p&&p.scenes)?p.scenes.slice(0,8):[];
      const cards=scenes.map(s=>{
        const url=safeVitrineUrl(s.url);
        const media=url
          ?(s.type==='video'
            ?`<video controls playsinline preload="metadata" src="${escapeHTML(url)}"></video>`
            :`<img loading="eager" src="${escapeHTML(url)}" alt="${escapeHTML(s.headline||row?.title||'Okyanus EDT')}">`)
          :'';
        return `<article class="okyVCard">${media}<div><h3>${escapeHTML(s.headline||row?.title||'Okyanus EDT')}</h3><p>${escapeHTML(s.text||'')}</p>${s.cta?`<span class="okyVCTA">${escapeHTML(s.cta)}</span>`:''}</div></article>`;
      }).join('');
      const body=cards
        ?`<div class="okyVGrid">${cards}</div>`
        :`<div class="okyVEmpty"><b>Okyanus Vitrini</b><span>Yeni içerik hazırlanıyor.</span></div>`;
      return `<section id="okyanus-vitrini" class="okyVitrine" data-published-at="${escapeHTML(row?.published_at||'')}"><div class="okyVHead"><small>OKYANUS EDT</small><h2>Okyanus Vitrini</h2></div>${body}</section><style id="oky-vitrine-style-v13">.okyVitrine{max-width:1180px;margin:28px auto;padding:22px}.okyVHead h2{margin:4px 0 16px;color:#07345d}.okyVGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}.okyVCard{overflow:hidden;border-radius:18px;background:#fff;box-shadow:0 10px 30px #06233d18}.okyVCard img,.okyVCard video{display:block;width:100%;aspect-ratio:16/9;object-fit:cover;background:#061831}.okyVCard div{padding:16px}.okyVCard h3{margin:0 0 7px;color:#07345d}.okyVCard p{margin:0;line-height:1.5}.okyVCTA{display:inline-block;margin-top:10px;font-weight:700;color:#0b65b1}.okyVEmpty{min-height:220px;display:grid;place-content:center;gap:8px;text-align:center;border-radius:18px;background:#f4f8fb;color:#07345d}.okyVEmpty b{font-size:24px}.okyVEmpty span{color:#61788a}@media(max-width:700px){.okyVitrine{padding:14px}.okyVGrid{grid-template-columns:1fr}}</style>`;
    }

    async function homePageWithVitrine(env){
      const base=homePage();
      const placeholder=vitrineSectionHTML(null,{scenes:[]});
      try{
        if(!env.ADMIN_DB){
          console.error('VITRINE_ADMIN_DB_MISSING');
          return replaceHomeDigitalMenuShowcase(base,placeholder);
        }
        const active=(await env.ADMIN_DB.prepare(`SELECT id,project_id,title,payload_json,published_at FROM studio_publications WHERE slot='homepage_vitrine' AND active=1 ORDER BY published_at DESC LIMIT 2`).all()).results||[];
        if(active.length>1){
          console.error('VITRINE_MULTIPLE_ACTIVE_PUBLICATIONS',active.length);
          return replaceHomeDigitalMenuShowcase(base,placeholder);
        }
        const row=active[0]||null;
        if(!row)return replaceHomeDigitalMenuShowcase(base,placeholder);
        let p={};
        try{p=JSON.parse(row.payload_json||'{}')}
        catch(e){
          console.error('VITRINE_PAYLOAD_INVALID',e?.message||e);
          return replaceHomeDigitalMenuShowcase(base,placeholder);
        }
        return replaceHomeDigitalMenuShowcase(base,vitrineSectionHTML(row,p));
      }catch(e){
        console.error('VITRINE_FALLBACK',e?.message||e);
        return replaceHomeDigitalMenuShowcase(base,placeholder);
      }
    }

