(function(){
 function refresh(){var root=document.getElementById('denizHomeCards');if(!root)return;
 fetch('/api/b2b/products',{headers:{accept:'application/json'},cache:'no-store'}).then(function(r){if(!r.ok)throw Error('CATALOG_'+r.status);return r.json()}).then(function(j){if(!j.ok||!Array.isArray(j.products))return;
 var original=new Map(Array.from(root.querySelectorAll('a[href*="urun="]')).map(function(a){return [new URL(a.href).searchParams.get('urun'),a.querySelector('img')?.src||'']}));
 root.replaceChildren();j.products.slice(0,10).forEach(function(x){var a=document.createElement('a');a.className='sea-home-card';a.href='/deniz-urunleri-b2b?urun='+encodeURIComponent(x.id);a.setAttribute('aria-label',x.name+' ürününü incele');var img=document.createElement('img');img.alt=x.name;img.loading='lazy';img.src=x.image||original.get(String(x.id))||'';if(img.src) a.appendChild(img);var body=document.createElement('div');body.className='sea-home-card-body';var name=document.createElement('b');name.textContent=x.name;var price=document.createElement('strong');price.textContent=x.effectivePrice!=null?Number(x.effectivePrice).toLocaleString('tr-TR',{style:'currency',currency:'TRY'})+' / '+(x.unit||'kg'):x.price?x.price+' TL / '+(x.unit||'kg'):'Teklif isteyin';var cta=document.createElement('span');cta.textContent='Ürünü İncele →';body.append(name,price,cta);a.appendChild(body);root.appendChild(a)})
 }).catch(function(e){console.warn('HOME_CATALOG_FALLBACK',e)})}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',refresh,{once:true});else refresh()
})();
