    function corporateShell(title,kicker,body){
     return `<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#061831"><title>${escapeHTML(title)} | Okyanus EDT</title><style>
    *{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f3f7fa;color:#10283a}.top{position:sticky;top:0;z-index:5;background:#061831;color:#fff;padding:13px 18px;display:flex;justify-content:space-between;align-items:center;gap:12px}.top a{color:#fff;text-decoration:none;font-weight:900}.wrap{max-width:1100px;margin:auto;padding:24px}.hero{background:linear-gradient(135deg,#061831,#0b4c78);color:#fff;border-radius:20px;padding:30px;margin-bottom:18px}.hero small{color:#8dd7f3;font-weight:900;letter-spacing:.12em}.hero h1{font-size:38px;margin:8px 0}.hero p{max-width:760px;color:#d8e9f4;line-height:1.7}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.card{background:#fff;border:1px solid #d7e4ec;border-radius:15px;padding:20px}.card h2,.card h3{color:#061831}.card p,.card li{line-height:1.7}.wide{grid-column:1/-1}.pill{display:inline-block;padding:7px 10px;border-radius:999px;background:#e8f4fa;color:#0873ae;font-size:12px;font-weight:900;margin:3px}.cta{display:inline-block;margin-top:8px;padding:12px 15px;border-radius:9px;background:#087fc1;color:#fff;text-decoration:none;font-weight:900}.note{background:#eef6fa;border-left:4px solid #087fc1;padding:13px;border-radius:8px;line-height:1.6}.foot{margin-top:20px;padding:18px;border-radius:14px;background:#061831;color:#dcebf4}.foot a{color:#fff}
    @media(max-width:720px){.wrap{padding:12px}.hero{padding:21px}.hero h1{font-size:30px}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.top{padding:10px}.card{padding:16px}}
    </style></head><body><header class="top"><b>OKYANUS EDT · ${escapeHTML(kicker)}</b><a href="/">← Ana Sayfa</a></header><main class="wrap">${body}<div class="foot"><b>Okyanus EDT</b> · Profesyonel HORECA Tedarik · <a href="/iletisim">İletişim</a> · <a href="/gizlilik">Gizlilik</a> · <a href="/yardim">Yardım</a></div></main><style id="oky-pwa-style">#oky-pwa-install{position:fixed;left:16px;bottom:18px;z-index:99999;border:0;border-radius:999px;padding:12px 17px;background:#07345d;color:#fff;font:800 14px Arial,sans-serif;box-shadow:0 8px 25px rgba(3,45,83,.28);display:none;cursor:pointer}@media(max-width:700px){#oky-pwa-install{left:12px;bottom:18px;padding:11px 14px;font-size:13px}}</style><button id="oky-pwa-install" type="button" aria-label="Okyanus EDT uygulamasını cihaza kaydet">📲 UYGULAMAYI KAYDET</button><script>(function(){var p=null,b=document.getElementById('oky-pwa-install');if(!b)return;var standalone=(window.matchMedia&&window.matchMedia('(display-mode: standalone)').matches)||navigator.standalone===true;if('serviceWorker' in navigator)window.addEventListener('load',function(){navigator.serviceWorker.register('/sw.js',{scope:'/'}).catch(function(){})});window.addEventListener('beforeinstallprompt',function(e){e.preventDefault();p=e;if(!standalone)b.style.display='block'});window.addEventListener('appinstalled',function(){p=null;b.style.display='none'});var ios=/iphone|ipad|ipod/i.test(navigator.userAgent);if(ios&&!standalone)b.style.display='block';b.addEventListener('click',async function(){if(p){p.prompt();try{await p.userChoice}catch(e){}p=null;b.style.display='none';return}if(ios){alert('Safari: Paylaş düğmesi → Ana Ekrana Ekle');return}alert('Tarayıcı menüsünden “Uygulamayı yükle” veya “Ana ekrana ekle” seçeneğini kullanabilirsiniz.')})})();</script></body></html>`}
    function aboutPage(){
     return corporateShell("Hakkımızda","HAKKIMIZDA",`<section class="hero"><small>İSTANBUL'DAN PROFESYONEL MUTFAKLARA</small><h1>Gıda tedarikinden işletme çözümlerine.</h1><p>Okyanus EDT; restoran, kafe, otel, lokanta, büfe ve endüstriyel mutfakların profesyonel tedarik ve dijital işletme çözüm ortağıdır. Yeni V2 mimarisinde ürün ve teklif akışını, işletmelerin maliyet ve mutfak çalışmalarını destekleyen profesyonel araçlarla aynı çatı altında buluşturur.</p></section>
    <section class="grid"><article class="card wide"><h2>Okyanus EDT</h2><p>Profesyonel mutfakların tedarik ihtiyaçlarına yönelik ürün ve işletme çözümleri sunuyoruz. Ana odağımız, işletmenin ihtiyaç duyduğu ürünü kolayca bulması, seçmesi ve teklif talebini hızlı biçimde oluşturmasıdır.</p><span class="pill">Profesyonel HORECA Tedarik</span><span class="pill">Ürün & Teklif</span><span class="pill">COST & Maliyet</span><span class="pill">ÇEŞNİ</span><span class="pill">COST Radar</span><span class="pill">Akademi</span></article>
    <article class="card"><h3>Misyonumuz</h3><p>Profesyonel mutfaklara güvenilir tedarik, hızlı çözüm ve işletme verimliliğini destekleyen araçlar sunmak; ürün seçiminden maliyet kontrolüne kadar daha kontrollü bir çalışma deneyimi oluşturmaktır.</p></article>
    <article class="card"><h3>Vizyonumuz</h3><p>Gıda tedariki ile dijital işletme araçlarını bir araya getiren, profesyonel mutfakların uzun vadeli çözüm ortağı olan güçlü ve sürdürülebilir bir Okyanus EDT ekosistemi geliştirmektir.</p></article>
    <article class="card"><h3>Çalışma İlkelerimiz</h3><p><b>Kalite:</b> Güvenilir kaynak.<br><b>Güven:</b> Uzun vadeli iş ortaklığı.<br><b>Hızlı Çözüm:</b> Zamanında ve anlaşılır süreç.<br><b>Sürdürülebilirlik:</b> Daha iyi yarınları destekleyen yaklaşım.</p></article>
    <article class="card"><h3>Kimler İçin?</h3><p>Restoran ve kafeler, oteller, catering ve yemekhaneler, profesyonel mutfaklar ve kurumsal gıda operasyonları için ürün, teklif ve işletme araçları.</p></article>
    <article class="card wide"><h3>Neden Okyanus EDT?</h3><p>Güvenilir toptan tedarik yaklaşımı, profesyonel reçete ve mutfak çalışmaları, gerçek maliyet ve kârlılık araçları, güncel içerik ve uzun vadeli iş ortaklığı anlayışı tek platformda buluşur.</p><a class="cta" href="/urunler">Ürünleri İncele</a> <a class="cta" href="/iletisim#mesaj-gonder">Mesaj Gönder</a></article></section>`)}
    function memberPage(){
     return corporateShell("Hızlı Form Bilgileri","HIZLI FORM BİLGİLERİ",`<section class="hero"><small>YEREL KAYIT · ÜYELİK/GİRİŞ DEĞİLDİR</small><h1>Teklif ve iletişim formlarını daha hızlı doldurun.</h1><p>Bu isteğe bağlı özellik üyelik veya giriş değildir; COST ve diğer modüller için zorunlu değildir. Bilgiler yalnız bu tarayıcıda en fazla 365 gün saklanır ve teklif/iletişim formlarındaki boş alanları doldurur.</p></section><section class="grid"><article class="card wide"><h2>Hızlı Form Bilgileri</h2><p class="note"><b>Ortak cihaz uyarısı:</b> Bu bilgileri yalnız size ait cihazda kaydedin. Parola, kimlik veya ödeme bilgisi girmeyin.</p><form id="memberForm" novalidate><div class="memberGrid"><label for="memberFirst">Ad *<input id="memberFirst" name="firstName" autocomplete="given-name" autocapitalize="words" maxlength="60" required><small class="fieldError" id="errFirst"></small></label><label for="memberLast">Soyad *<input id="memberLast" name="lastName" autocomplete="family-name" autocapitalize="words" maxlength="60" required><small class="fieldError" id="errLast"></small></label><label for="memberPhone">Telefon *<input id="memberPhone" name="phone" type="tel" inputmode="tel" autocomplete="tel" maxlength="24" required placeholder="05xx xxx xx xx"><small class="fieldError" id="errPhone"></small></label><label for="memberEmail">E-posta *<input id="memberEmail" name="email" type="email" inputmode="email" autocomplete="email" maxlength="140" required><small class="fieldError" id="errEmail"></small></label><label class="wideField" for="memberBusiness">İşletme adı<input id="memberBusiness" name="business" autocomplete="organization" autocapitalize="words" maxlength="140"><small class="fieldError" id="errBusiness"></small></label></div><label class="noticeCheck"><input name="kvkk" type="checkbox" required> <span><a href="/kvkk" target="_blank" rel="noopener">KVKK Aydınlatma Metni</a>'ni ve bilgilerin bu cihazda tutulacağını okudum.</span></label><button class="cta" type="submit">Hızlı Form Bilgilerini Kaydet</button> <button class="cta danger" id="clearProfile" type="button">Hızlı Form Bilgilerini Sil</button><div id="memberStatus" class="note" role="status" aria-live="polite">Henüz işlem yapılmadı.</div></form></article></section><style>.memberGrid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.wideField{grid-column:1/-1}#memberForm input{display:block;width:100%;min-height:48px;margin-top:6px;padding:12px;border:1px solid #c9dbe6;border-radius:9px;font:16px Arial,sans-serif}#memberForm input[aria-invalid="true"]{border-color:#b42334;outline:2px solid #b4233433}.fieldError{display:block;min-height:18px;color:#a3182b;margin-top:4px}.noticeCheck{display:flex;gap:10px;align-items:flex-start;margin:14px 0}.noticeCheck input{width:22px!important;min-height:22px!important;margin:0!important}.danger{background:#8b2433!important}#memberStatus{margin-top:14px;font-weight:800}@media(max-width:650px){.memberGrid{grid-template-columns:1fr}.wideField{grid-column:auto}.cta{width:100%;margin:5px 0;min-height:48px}}</style><script>(function(){var K='okyanusLocalProfileV2',OLD='okyanusMemberProfileV1',YEAR=365*24*60*60*1000,f=document.getElementById('memberForm'),st=document.getElementById('memberStatus');function clean(v){return String(v||'').trim().replace(/\\s+/g,' ')}function digits(v){return String(v||'').replace(/\\D/g,'')}function err(name,msg){var el=f.elements[name],box=document.getElementById({firstName:'errFirst',lastName:'errLast',phone:'errPhone',email:'errEmail',business:'errBusiness'}[name]);el.setAttribute('aria-invalid',msg?'true':'false');box.textContent=msg||'';return!msg}function validate(){var p={firstName:clean(f.elements.firstName.value),lastName:clean(f.elements.lastName.value),phone:clean(f.elements.phone.value),email:clean(f.elements.email.value),business:clean(f.elements.business.value)},ok=true,nameRe=/(?=(?:.*\\p{L}){2})^[\\p{L}][\\p{L} '\\-]{1,59}$/u,phoneRe=/^\\+?[0-9 ()-]+$/,n=digits(p.phone);ok=err('firstName',nameRe.test(p.firstName)?'':'Ad en az 2 harf olmalı; rakam ve emoji kullanmayın.')&&ok;ok=err('lastName',nameRe.test(p.lastName)?'':'Soyad en az 2 harf olmalı; rakam ve emoji kullanmayın.')&&ok;ok=err('phone',phoneRe.test(p.phone)&&n.length>=10&&n.length<=15&&(p.phone.match(/\\+/g)||[]).length<=1?'':'Telefon yalnız rakam, boşluk, parantez, tire ve başta + içerebilir; 10–15 rakam olmalıdır.')&&ok;ok=err('email',/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(p.email)?'':'Geçerli bir e-posta adresi girin.')&&ok;ok=err('business',!p.business||p.business.length>=2?'':'İşletme adı en az 2 karakter olmalıdır.')&&ok;return{ok:ok,p:p}}function load(){try{var raw=localStorage.getItem(K),p=raw?JSON.parse(raw):null;if(p&&p.expiresAt&&Date.parse(p.expiresAt)<=Date.now()){localStorage.removeItem(K);p=null;st.textContent='Süresi dolan yerel profil güvenli biçimde silindi.'}if(!p){var old=JSON.parse(localStorage.getItem(OLD)||'null');if(old)p=old}if(p)['firstName','lastName','phone','email','business'].forEach(function(k){if(f.elements[k])f.elements[k].value=clean(p[k])})}catch(e){try{localStorage.removeItem(K)}catch(_){}st.textContent='Bozuk yerel kayıt temizlendi; bilgileri yeniden kontrol edin.'}}f.onsubmit=function(e){e.preventDefault();var v=validate();if(!v.ok){st.textContent='İşaretlenen alanları düzeltin.';var bad=f.querySelector('[aria-invalid="true"]');if(bad)bad.focus();return}if(!f.elements.kvkk.checked){st.textContent='KVKK bilgilendirmesini okuyup kutuyu işaretleyin.';f.elements.kvkk.focus();return}var now=new Date(),p=Object.assign({schemaVersion:2,purpose:'FORM_PREFILL',noticeVersion:'2026-09-08-v1',acknowledgedAt:now.toISOString(),savedAt:now.toISOString(),expiresAt:new Date(now.getTime()+YEAR).toISOString()},v.p);try{localStorage.setItem(K,JSON.stringify(p));localStorage.removeItem(OLD);st.textContent='Hızlı form bilgileri kaydedildi; teklif ve iletişim formlarındaki boş alanlar doldurulacak.';f.elements.kvkk.checked=false}catch(e){st.textContent='Profil kaydedilemedi. Tarayıcının yerel depolama iznini kontrol edin.'}};document.getElementById('clearProfile').onclick=function(){if(!confirm('Bu cihazdaki hızlı form bilgileri silinsin mi?'))return;try{localStorage.removeItem(K);localStorage.removeItem(OLD);f.reset();st.textContent='Hızlı form bilgileri silindi.'}catch(e){st.textContent='Profil silinemedi; tarayıcı depolama ayarını kontrol edin.'}};load()})();</script>`)
    }

    function memberNoticeVersion(){return "2026-09-16-v2"}
    function memberPrivacyNoticeHTML(){return `<section class="memberNotice" id="memberNotice" aria-labelledby="noticeTitle"><div class="noticeTag">İŞLETMENİZE ÖZEL ÇALIŞMA ALANI · SÜRÜM ${memberNoticeVersion()}</div><h2 id="noticeTitle">Benim Okyanus’um: veriniz ve kullanım koşulları</h2><p><b>Bu panel işletme hesabınıza özeldir.</b> COST, reçete ve özel çalışma kayıtları başka işletmelere açılmaz. Okyanus satış personeline bu özel çalışma kayıtlarını görüntüleme yetkisi verilmez. İşletmenizin kendi yetkilendirdiği hesap kullanıcıları rol sınırları içinde erişebilir. Yayımlamayı seçtiğiniz QR menü, müşterilerinizin görmesi için herkese açık olur; teklif ve iletişim talepleri ilgili satış ekibine iletilir.</p><p><b>Erişim sınırı:</b> Bu uygulamada çalışanlara özel kayıtları açan bir satış ekranı bulunmaz. Hizmetin işletilmesi için yetkilendirilmiş teknik yöneticilerin altyapı erişimi ve kanunen yetkili mercilere yapılması zorunlu açıklamalar ayrı konulardır. Altyapıda teknik olarak mümkün olan erişimin hiç mümkün olmadığı taahhüt edilmez.</p><h3>Kişisel veriler ve güvenlik kayıtları</h3><p>Veri sorumlusu: <b>OKYANUS EDT – Orhan Güngör</b>, Oruçreis Mahallesi, 600. Sokak, No: 21, İç Kapı No: 4, Esenler / İstanbul. Başvuru: <a href="mailto:info@okyonusedt.com">info@okyonusedt.com</a>. Üyelikte ad, soyad, işletme, e-posta, isteğe bağlı telefon, parola doğrulama bilgisi ve işletme kayıtları; sayfa girişlerinde zaman, ziyaret edilen sayfanın yolu, rastgele ziyaret kodunun özeti ve varsa hesap kimliği elektronik olarak işlenir. Bu özel sayfa giriş kayıtlarına ham IP, PIN, mesaj veya reçete içeriği yazılmaz.</p><p>Üyelik ve kayıtlar hizmet sözleşmesinin kurulması/ifası için KVKK m.5/2-c; güvenlik ve giriş kayıtları hak ve özgürlükler gözetilerek hizmetin güvenliği için m.5/2-f; yasal yükümlülükler ve hak talepleri ilgili durumlarda m.5/2-ç/e kapsamında değerlendirilir. Zorunlu oturum çerezi ve bilgilendirme kayıt çerezi kullanılır. Bu bilgilendirme pazarlama veya ticari elektronik ileti izni değildir; böyle bir izin ayrıca alınır.</p><p><b>40 günlük özel giriş günlüğü:</b> Bu uygulamanın sayfa girişi ve “Okudum” günlükleri oluşturuldukları andan itibaren 40 gün geçerlidir. Süresi dolan kayıtlar işlem amacıyla kullanılmaz ve otomatik temizlik çalışmasında silinir. Bu süre reçete, COST veya menü kayıtlarının 40 günde silinmesi anlamına gelmez. Üyelik sözleşmesi kabul kanıtları ve mevzuat gereği tutulması zorunlu diğer kayıtlar kendi saklama sürelerine tabidir. Bulut sağlayıcısının yedek ve platform günlükleri bu özel günlükten ayrıdır.</p><p>Veriler, hizmet için gerekli ölçüde teknik barındırma/e-posta sağlayıcıları ve yasal şartlar oluştuğunda yetkili mercilerle işlenebilir. Cloudflare bulut altyapısı kullanılır; yurt dışı aktarım söz konusuysa KVKK m.9 uyarınca uygun aktarım güvencesinin sağlanması veri sorumlusunun yükümlülüğüdür. Verinin işlenip işlenmediğini öğrenme, bilgi isteme, düzeltme, şartları oluştuğunda silme/yok etme, aktarımı öğrenme ve KVKK m.11 kapsamındaki diğer haklar için yukarıdaki kanaldan başvurabilirsiniz. Ayrıntılar: <a href="/kvkk" target="_blank" rel="noopener">KVKK Aydınlatma Metni</a> ve <a href="/gizlilik" target="_blank" rel="noopener">Gizlilik Politikası</a>.</p><h3>Hesap ve işlem sorumluluğu</h3><p>Hesabınızın güvenliğinden, giriş bilgilerinin paylaşılmamasından, girilen verinin doğruluğundan ve hesap sonuçlarının uygulanmadan önce mesleki olarak kontrol edilmesinden sorumlusunuz. Araçlar karar desteğidir; mali, hukuki, tıbbi veya gıda güvenliği danışmanlığı değildir. Okyanus EDT, kullanıcının hatalı verisi veya sonuçları kontrol etmeden uygulaması nedeniyle oluşan sonuçlardan, kanunen sorumluluğu bulunmadığı ölçüde sorumlu tutulamaz. Okyanus EDT’nin kastı, ağır kusuru, kişisel veri güvenliği yükümlülükleri ve emredici kanun hükümlerinden doğan sorumluluğu ortadan kaldırılmaz.</p><h3>Uyuşmazlıklar</h3><p>Türkiye Cumhuriyeti hukuku uygulanır. Ticari uyuşmazlıklarda görevli ve kanunen yetkili yerel Asliye Ticaret Mahkemeleri ve ilgili başvuru mercileri; tüketici sıfatı bulunan hallerde tüketici hakem heyetleri/mahkemeleri yetkilidir. Kanuni ve kesin yetki kuralları saklıdır. Bu metin tek başına herkesi belirli bir şehir mahkemesine bağlayan yetki sözleşmesi oluşturmaz.</p><p><a href="/uyelik-bildirgesi" target="_blank" rel="noopener">Üyelik Bildirgesi ve Kullanım Koşulları</a> kayıt sırasında ayrıca kabul edilir. Aşağıdaki kutu yalnız bu bilgilendirmenin okunduğunu kaydeder; hizmet kullanımı veya pazarlama rızası değildir.</p><label class="noticeRead"><input id="noticeRead" type="checkbox"> <span>Bilgilendirmeyi okudum.</span></label><p id="noticeStatus" role="status" aria-live="polite"></p></section><button class="noticeReopen" id="noticeReopen" type="button" hidden>Üyelik bilgilendirmesini yeniden oku</button>`}
    const memberVisitSchemaSetupCache=new WeakMap();
    async function ensureMemberVisitLogSchema(env){
     if(!env||!env.DB)throw Error("VISIT_LOG_DATABASE_REQUIRED");const cache=memberVisitSchemaSetupCache;if(cache.has(env.DB))return cache.get(env.DB);
     const setup=(async()=>{await memberD1Run(env.DB.prepare(`CREATE TABLE IF NOT EXISTS member_visit_logs_v1 (id TEXT PRIMARY KEY,event_type TEXT NOT NULL,path TEXT NOT NULL,visitor_hash TEXT NOT NULL,user_id TEXT,business_id TEXT,document_version TEXT,created_at TEXT NOT NULL,expires_at TEXT NOT NULL)`));await memberD1Run(env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_member_visit_logs_expiry ON member_visit_logs_v1(expires_at)`))})();cache.set(env.DB,setup);try{await setup}catch(e){if(cache.get(env.DB)===setup)cache.delete(env.DB);throw e}
    }
    const memberVisitPurgeCache=new WeakMap();
    async function purgeMemberVisitLogs(env,force=false){
     if(!env||!env.DB)return;await ensureMemberVisitLogSchema(env);const cache=memberVisitPurgeCache,now=Date.now(),last=cache.get(env.DB)||0;if(!force&&now-last<3600000)return;cache.set(env.DB,now);try{await memberD1Run(env.DB.prepare(`DELETE FROM member_visit_logs_v1 WHERE expires_at<=?`).bind(new Date(now).toISOString()))}catch(e){if(cache.get(env.DB)===now)cache.delete(env.DB);throw e}
    }
    async function writeMemberVisitLog(request,env,eventType,path,visitorToken,me=null){
     await ensureMemberVisitLogSchema(env);const now=Date.now();await memberD1Run(env.DB.prepare(`INSERT INTO member_visit_logs_v1(id,event_type,path,visitor_hash,user_id,business_id,document_version,created_at,expires_at) VALUES(?,?,?,?,?,?,?,?,?)`).bind(memberId("visit"),eventType,path,await memberSHA(visitorToken),me&&me.user_id||null,me&&me.business_id||null,eventType==="NOTICE_READ"?memberNoticeVersion():null,new Date(now).toISOString(),new Date(now+40*86400000).toISOString()));await purgeMemberVisitLogs(env)
    }
    async function memberNoticeAckAPI(request,env){
     if(request.method!=="POST")return memberJSON({ok:false,error:"METHOD_NOT_ALLOWED"},405,{Allow:"POST"});if(!memberSameOrigin(request)||!request.headers.get("origin"))return memberJSON({ok:false,error:"ORIGIN_REJECTED"},403);if(!env||!env.DB)return memberJSON({ok:false,error:"VISIT_LOG_DATABASE_REQUIRED",message:"Okuma kaydı şu anda saklanamıyor. Bilgilendirme açık kalacaktır; giriş yapabilirsiniz."},503);
     let body;try{const raw=await request.text();if(new TextEncoder().encode(raw).length>1024)return memberJSON({ok:false,error:"PAYLOAD_TOO_LARGE"},413);body=JSON.parse(raw)}catch{return memberJSON({ok:false,error:"INVALID_JSON"},400)}if(!body||body.read!==true||body.version!==memberNoticeVersion())return memberJSON({ok:false,error:"NOTICE_VERSION_REQUIRED"},400);
     const cookies=memberCookies(request),token=/^[a-f0-9-]{36}$/i.test(cookies.oky_notice_visit_v2||"")?cookies.oky_notice_visit_v2:crypto.randomUUID();let me=null;if(memberPortalEnabled(env))me=await memberSession(request,env);await writeMemberVisitLog(request,env,"NOTICE_READ","/uye",token,me);return memberJSON({ok:true,version:memberNoticeVersion(),retentionDays:40},200,{"set-cookie":`oky_notice_visit_v2=${token}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=3456000`})
    }

    function memberTermsPage(){return corporateShell("Üyelik Bildirgesi ve Kullanım Koşulları","ÜYELİK BİLDİRGESİ",`<section class="hero"><small>SÜRÜM ${memberNoticeVersion()}</small><h1>Benim Okyanus’um Üyelik Bildirgesi</h1><p>Ürün Seç, COST Radar ve Fotoğrafla Teklif açık araçlardır. Diğer özel iş araçları aktif işletme hesabıyla kullanılır.</p></section>${memberPrivacyNoticeHTML().split('<label class="noticeRead">')[0]+'</section>'}<section class="card"><h2>Üyelik sözleşmesi</h2><p>Üye işletme adına yetkili olduğunu, hesap bilgilerinin doğru olduğunu ve hesap güvenliğini koruyacağını beyan eder. İzinsiz erişim ve hukuka aykırı kullanım yasaktır. Üyelik koşulları kayıt sırasında ayrıca kabul edilir; bunun kanıtı kullanıcı kimliği, metin sürümü, zaman ve IP özetiyle mevcut üyelik kabul tablosunda saklanır. Bu sözleşme kabul kanıtı 40 günlük özel sayfa giriş günlüğünden ayrıdır.</p><p>Esaslı koşul değişiklikleri yeni sürümle bildirilir. Hesap/veri talepleri kurumsal iletişim kanalıyla iletilebilir. Bilgilendirmeyi yeniden okumak veya giriş yapmak için <a href="/uye">Üye Girişi</a>.</p></section>`)}

    function memberWorkspacePageV2(me){const business=escapeHTML(me.business_display_name||me.business_name),name=escapeHTML((me.first_name||"")+" "+(me.last_name||"")),email=escapeHTML(me.email||""),phone=escapeHTML(me.phone||"Belirtilmedi"),role=me.role==="owner"?"İşletme sahibi":"Yetkili kullanıcı";return `<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Benim Okyanus’um | ${business}</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial;background:#f3f7fa;color:#10283a}.top{background:#061831;color:#fff;padding:14px 18px;display:flex;justify-content:space-between;align-items:center;gap:10px}.top a{color:#fff}.logout{min-height:44px;border:1px solid #ffffff55;background:transparent;color:#fff;border-radius:9px;padding:9px 14px;font-weight:900}.wrap{width:min(1450px,calc(100% - 28px));margin:auto;padding:22px 0}.hero{background:linear-gradient(135deg,#061831,#0b4c78);color:#fff;border-radius:18px;padding:24px}.hero small{color:#8dd7f3;font-weight:900}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:14px}.card{min-width:0;background:#fff;border:1px solid #d7e4ec;border-radius:14px;padding:18px}.card p,.card dd{overflow-wrap:anywhere}.card a{display:inline-block;margin-top:8px;color:#087fc1;font-weight:900}.profile{grid-column:span 2}.profile dl{display:grid;grid-template-columns:140px minmax(0,1fr);gap:8px;margin:0}.profile dt{font-weight:900}.profile dd{margin:0}.secure{border-left:5px solid #15915b}.legal{border-left:5px solid #d49b16}@media(max-width:800px){.wrap{width:100%;padding:10px}.grid{grid-template-columns:1fr}.profile{grid-column:auto}.profile dl{grid-template-columns:1fr}.top{flex-wrap:wrap}.hero,.card{padding:15px}}</style></head><body><header class="top"><b>BENİM OKYANUS’UM</b><button class="logout" id="logout">Güvenli Çıkış</button></header><main class="wrap"><section class="hero"><small>${business} · ${escapeHTML(role)}</small><h1>Hoş geldiniz, ${name}.</h1><p>Bu alan yalnız sizin işletme hesabınıza bağlıdır. Başka işletmelerin kayıtları burada görüntülenmez.</p></section><section class="grid"><article class="card profile"><h2>İşletme ve hesap bilgilerim</h2><dl><dt>İşletme</dt><dd>${business}</dd><dt>Yetkili</dt><dd>${name}</dd><dt>E-posta</dt><dd>${email}</dd><dt>Telefon</dt><dd>${phone}</dd><dt>Rol</dt><dd>${escapeHTML(role)}</dd></dl></article><article class="card secure"><h2>Güvenli oturum</h2><p>E-posta doğrulamanız tamamlandı. Oturumunuz güvenli çerezle korunuyor.</p></article><article class="card"><h2>Dijital Menüm</h2><p>Menünüzü oluşturun, ürünleri yönetin ve QR menünüzü yayınlayın.</p><a href="/dijital-menu">Dijital Menüye Git →</a></article><article class="card"><h2>Kolay Reçetelerim</h2><p>Malzemeleri, miktarları ve birim maliyetleri girin; toplam ve porsiyon maliyetini anında hesaplayın.</p><a href="/kolay-recete">Kolay Reçeteyi Aç →</a></article><article class="card"><h2>COST çalışma alanım</h2><p>Sunucu kayıtları yalnız bu işletme hesabının kimliğiyle saklanır.</p><a href="/cost">COST Merkezini Aç →</a></article><article class="card"><h2>Akademi</h2><p>İşletme eğitimlerine ve profesyonel araçlara ulaşın.</p><a href="/akademi">Akademiye Git →</a></article><article class="card legal"><h2>Üyelik ve hukuk</h2><p>Kabul ettiğiniz üyelik koşullarını ve KVKK bilgilendirmesini inceleyin.</p><a href="/uyelik-bildirgesi">Üyelik Bildirgesi →</a><br><a href="/kvkk">KVKK Aydınlatma Metni →</a></article><article class="card"><h2>Destek ve hesap işlemleri</h2><p>Bilgi düzeltme, hesap kapatma ve veri talepleri için iletişim kanalını kullanın.</p><a href="/iletisim">Destek Talebi Oluştur →</a></article></section></main><script>logout.onclick=async()=>{await fetch('/api/member/logout',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});location.href='/uye'};</script></body></html>`}

    function easyRecipePage(me){return `<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Kolay Reçete | Okyanus EDT</title><style>*{box-sizing:border-box}body{margin:0;background:#edf3f7;color:#10283a;font-family:Arial,sans-serif}.oraApp{width:min(100%,760px);margin:auto;min-height:100dvh;background:#f6f8fa}.oraBar{position:sticky;top:0;z-index:20;display:grid;grid-template-columns:48px minmax(0,1fr) auto;align-items:center;gap:8px;min-height:64px;padding:8px 12px;background:#062d50;color:#fff}.oraBack,.oraIcon{min-width:44px;min-height:44px;border:0;border-radius:12px;background:#ffffff18;color:#fff;font-size:18px}.oraTitle{text-align:center;min-width:0}.oraTitle b,.oraTitle small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.oraTitle small{color:#a9d9f2}.oraMain{padding:12px 12px calc(160px + env(safe-area-inset-bottom))}.oraCard{margin-bottom:12px;padding:14px;border:1px solid #d4e1e9;border-radius:16px;background:#fff;box-shadow:0 5px 16px #00213b0d}.oraCard h2{margin:0 0 10px;font-size:16px}.oraGrid{display:grid;grid-template-columns:1fr 120px;gap:9px}.oraField{display:grid;gap:5px;font-size:12px;font-weight:800}.oraField input,.oraField select{width:100%;min-width:0;min-height:46px;padding:10px;border:1px solid #bfd2df;border-radius:10px;font:16px Arial;background:#fff}.oraToggle{display:flex;justify-content:space-between;align-items:center;gap:10px}.oraToggle input{width:24px;height:24px}.oraIngredient{display:grid;grid-template-columns:minmax(0,1fr) 82px 72px 92px 44px;gap:6px;align-items:end;padding:10px 0;border-bottom:1px solid #e6eef3}.oraIngredient input,.oraIngredient select{width:100%;min-width:0;min-height:44px;border:1px solid #c7d8e3;border-radius:9px;padding:8px;font-size:16px}.oraRemove{min-width:44px;min-height:44px;border:0;border-radius:9px;background:#fff0f2;color:#b10f2e;font-weight:900}.oraAdd{width:100%;min-height:48px;margin-top:10px;border:1px dashed #0b78b6;border-radius:11px;background:#edf8fd;color:#075985;font-weight:900}.oraSummary{background:linear-gradient(135deg,#073b63,#0b6e9f);color:#fff}.oraSumRow{display:flex;justify-content:space-between;gap:10px;padding:8px 0;border-bottom:1px solid #ffffff24}.oraSumRow strong{font-size:18px}.oraList button{width:100%;text-align:left;min-height:52px;border:0;border-bottom:1px solid #e4edf2;background:#fff;padding:10px}.oraActions{position:fixed;left:0;right:0;bottom:0;z-index:25;display:grid;grid-template-columns:1fr 1.4fr;gap:8px;padding:10px 12px calc(10px + env(safe-area-inset-bottom));background:#fff;border-top:1px solid #cadbe5}.oraActions button{min-height:50px;border:0;border-radius:11px;font-weight:900}.oraDraft{background:#eaf3f8;color:#073b63}.oraSave{background:#087fc1;color:#fff}.oraStatus{min-height:20px;margin-top:8px;font-weight:800;overflow-wrap:anywhere}@media(max-width:560px){.oraGrid{grid-template-columns:1fr}.oraIngredient{grid-template-columns:minmax(0,1fr) 78px 44px}.oraIngredient .oraUnit{grid-column:1/2}.oraIngredient .oraCost{grid-column:2/3}}@media(max-width:340px){.oraIngredient{grid-template-columns:minmax(0,1fr) 44px}.oraIngredient .oraQty,.oraIngredient .oraUnit,.oraIngredient .oraCost{grid-column:1/-1}.oraActions{grid-template-columns:1fr}}@media(min-width:900px){.oraApp{width:min(1180px,calc(100% - 32px))}.oraMain{display:grid;grid-template-columns:1.3fr .7fr;gap:14px}.oraIdentity,.oraList{grid-column:1/-1}.oraSummary{position:sticky;top:78px;align-self:start}.oraActions{width:min(1180px,calc(100% - 32px));margin:auto}}@media print{.oraBar,.oraActions,.oraAdd,.oraRemove{display:none!important}.oraMain{padding:0}}</style></head><body><div class="oraApp"><header class="oraBar"><button class="oraBack" id="oraBack" type="button" aria-label="Geri">←</button><div class="oraTitle"><b>Kolay Reçete</b><small>${escapeHTML(me.business_display_name||me.business_name)}</small></div><button class="oraIcon" id="oraNew" type="button" aria-label="Yeni reçete">＋</button></header><main class="oraMain"><section class="oraCard oraIdentity"><div class="oraGrid"><label class="oraField">Reçete adı<input id="rTitle" maxlength="160" placeholder="Örn. Akdeniz Pizza"></label><label class="oraField">Porsiyon<input id="rServings" type="number" inputmode="decimal" min="0.01" value="1"></label><label class="oraField">Kategori<input id="rCategory" maxlength="80" placeholder="Örn. Ana Yemek"></label><label class="oraToggle">Varyasyonlu reçete <input id="rVariation" type="checkbox"></label></div><label class="oraField" id="variationBox" hidden>Varyasyon adı<input id="rVariationName" maxlength="80" placeholder="Örn. Küçük"></label></section><section class="oraCard"><h2>İçindekiler</h2><div id="ingredients"></div><button class="oraAdd" id="addIngredient" type="button">＋ Malzeme Ekle</button></section><section class="oraCard oraSummary"><h2>Maliyet Özeti</h2><div class="oraSumRow"><span>Toplam maliyet</span><strong id="totalCost">0,00 ₺</strong></div><div class="oraSumRow"><span>Porsiyon maliyeti</span><strong id="portionCost">0,00 ₺</strong></div><div class="oraStatus" id="recipeStatus" role="status"></div></section><section class="oraCard oraList"><h2>Kayıtlı Reçetelerim</h2><div id="recipeList">Yükleniyor…</div></section></main><nav class="oraActions"><button class="oraDraft" id="saveDraft" type="button">Taslak Kaydet</button><button class="oraSave" id="saveRecipe" type="button">Reçeteyi Kaydet</button></nav></div><script>(()=>{
    const $=id=>document.getElementById(id),fmt=n=>(Number(n)||0).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₺';
    let state={id:'',version:0,ingredients:[],steps:[]},dirty=false,saving=false,revision=0;
    const markDirty=()=>{dirty=true;revision++},status=$('recipeStatus');
    const statusHome=document.querySelector('.oraActions');if(statusHome){statusHome.prepend(status);status.style.gridColumn='1 / -1';status.style.margin='0';status.style.fontSize='13px'}
    const notify=text=>{status.textContent=text};
    function unitFactor(u){return(u==='g'||u==='ml')?0.001:1}
    function calc(){let total=0;state.ingredients.forEach(x=>total+=(Number(x.quantity)||0)*(Number(x.unitCost)||0)*unitFactor(x.unit));$('totalCost').textContent=fmt(total);$('portionCost').textContent=fmt(total/Math.max(.01,Number($('rServings').value)||1))}
    function row(x={name:'',quantity:0,unit:'g',unitCost:0}){if(saving)return;if(state.ingredients.length>=100){notify('Bir reçeteye en fazla 100 malzeme ekleyebilirsiniz.');return}state.ingredients.push(x);markDirty();render()}
    function render(){const box=$('ingredients');box.textContent='';state.ingredients.forEach((x,i)=>{const div=document.createElement('div');div.className='oraIngredient';[['name','Malzeme','text'],['quantity','Miktar','number'],['unitCost','Birim ₺','number']].forEach(([key,placeholder,type])=>{const input=document.createElement('input');input.type=type;input.placeholder=placeholder;input.value=x[key]??'';input.className=key==='quantity'?'oraQty':key==='unitCost'?'oraCost':'';input.setAttribute('aria-label',(i+1)+'. malzeme '+placeholder);if(type==='number'){input.min='0';input.step='any';input.inputMode='decimal';input.max=key==='quantity'?'10000000':'1000000000'}input.oninput=()=>{x[key]=type==='number'?Number(String(input.value).replace(',','.')):input.value;markDirty();calc()};div.appendChild(input)});const select=document.createElement('select');select.className='oraUnit';select.setAttribute('aria-label',(i+1)+'. malzeme birimi');['g','kg','ml','lt','adet'].forEach(unit=>{const option=document.createElement('option');option.value=unit;option.textContent=unit;option.selected=x.unit===unit;select.appendChild(option)});select.onchange=()=>{x.unit=select.value;markDirty();calc()};div.insertBefore(select,div.children[2]);const remove=document.createElement('button');remove.type='button';remove.className='oraRemove';remove.textContent='Sil';remove.onclick=()=>{if(saving)return;state.ingredients.splice(i,1);markDirty();render()};div.appendChild(remove);box.appendChild(div)});calc()}
    function payload(recordStatus){const title=$('rTitle').value.trim(),servings=Number($('rServings').value);if(!title)throw Error('Reçete adını yazın.');if(!Number.isFinite(servings)||servings<=0||servings>100000)throw Error('Porsiyon sayısı 0’dan büyük ve en fazla 100.000 olmalıdır.');const ingredients=[];state.ingredients.forEach((item,i)=>{const name=String(item.name||'').trim(),quantity=Number(item.quantity),unitCost=Number(item.unitCost);if(!name&&quantity===0&&unitCost===0)return;if(!name)throw Error((i+1)+'. malzemenin adını yazın.');if(!Number.isFinite(quantity)||quantity<0||quantity>1e7)throw Error((i+1)+'. malzemenin miktarını kontrol edin.');if(!Number.isFinite(unitCost)||unitCost<0||unitCost>1e9)throw Error((i+1)+'. malzemenin birim maliyetini kontrol edin.');if(!['g','kg','ml','lt','adet'].includes(item.unit))throw Error((i+1)+'. malzemenin birimini seçin.');ingredients.push({name,quantity,unit:item.unit,unitCost})});if(!ingredients.length)throw Error('En az bir malzemenin adını ve bilgilerini girin.');return{id:state.id,version:state.version,title,category:$('rCategory').value.trim(),servings,variation:$('rVariation').checked,variationName:$('rVariationName').value.trim(),ingredients,steps:state.steps||[],status:recordStatus}}
    async function responseData(response){let body;try{body=await response.json()}catch(_){throw Error('Sunucudan geçerli yanıt alınamadı. Reçete ekranda korundu.')}if(!response.ok||!body||!body.ok){if(response.status===401)throw Error('Oturumunuz sona erdi. Reçeteyi ekranda koruyarak yeniden giriş yapın.');if(response.status===409)throw Error('Reçetenin sürümü değişti. Kayıtlı listeyi kontrol ederek yeniden açın.');if(response.status===403)throw Error('Bu işlem için hesabınızın kayıt yetkisi bulunmuyor.');throw Error(body&&body.message||'Reçete hizmeti işlemi tamamlayamadı. Bilgileriniz ekranda korundu.')}return body}
    function setSaving(value){saving=value;['saveDraft','saveRecipe','oraNew','addIngredient'].forEach(id=>$(id).disabled=value);$('saveRecipe').textContent=value?'Kaydediliyor…':'Reçeteyi Kaydet'}
    async function save(recordStatus){if(saving)return;let data;try{data=payload(recordStatus)}catch(error){notify(error.message);return}const revisionAtStart=revision;setSaving(true);notify('Reçete kaydediliyor…');try{const response=await fetch('/api/member/recipes',{method:state.id?'PUT':'POST',headers:{'content-type':'application/json','accept':'application/json'},body:JSON.stringify(data)}),body=await responseData(response);if(!body.id||!Number.isInteger(Number(body.version))||Number(body.version)<1)throw Error('Sunucu kayıt kimliğini doğrulayamadı. Bilgileriniz ekranda korundu.');state.id=body.id;state.version=Number(body.version);dirty=revision!==revisionAtStart;notify(dirty?'✓ Reçete kaydedildi. Sonradan yaptığınız değişiklikleri ayrıca kaydedin.':'✓ Reçete güvenle kaydedildi.');try{await loadList()}catch(_){notify('✓ Reçete kaydedildi. Kayıtlı liste yenilenemedi; kayıt kimliği ve sürümü korundu.')}}catch(error){notify(error.message||'Kayıt tamamlanamadı. Reçete bilgileri ekranda korundu.')}finally{setSaving(false)}}
    async function loadList(){const response=await fetch('/api/member/recipes',{headers:{accept:'application/json'}}),body=await responseData(response),box=$('recipeList');if(!Array.isArray(body.recipes))throw Error('Kayıtlı liste yanıtı doğrulanamadı.');box.textContent='';body.recipes.forEach(recipe=>{const button=document.createElement('button');button.type='button';button.textContent=recipe.title+' · '+recipe.servings+' porsiyon';button.onclick=()=>{if(saving)return;if(dirty&&!confirm('Kaydedilmemiş değişiklikler silinsin mi?'))return;state={id:recipe.id,version:Number(recipe.version),ingredients:recipe.ingredients||[],steps:recipe.steps||[]};$('rTitle').value=recipe.title;$('rCategory').value=recipe.category||'';$('rServings').value=recipe.servings;$('rVariation').checked=!!recipe.variation;$('rVariationName').value=recipe.variationName||'';$('variationBox').hidden=!recipe.variation;dirty=false;revision++;notify('Kayıtlı reçete açıldı.');render();scrollTo({top:0,behavior:'smooth'})};box.appendChild(button);const requested=new URLSearchParams(location.search).get('recipe');if(requested===recipe.id&&!window.__memberRecipeOpened){window.__memberRecipeOpened=true;button.onclick()}});if(!body.recipes.length)box.textContent='Henüz kayıtlı reçete yok.'}
    function fresh(){if(saving)return;state={id:'',version:0,ingredients:[],steps:[]};$('rTitle').value='';$('rCategory').value='';$('rServings').value=1;$('rVariation').checked=false;$('rVariationName').value='';$('variationBox').hidden=true;row();dirty=false;notify('')}
    $('addIngredient').onclick=()=>row();$('rVariation').onchange=()=>{$('variationBox').hidden=!$('rVariation').checked;markDirty()};$('rTitle').oninput=$('rCategory').oninput=$('rServings').oninput=$('rVariationName').oninput=()=>{markDirty();calc()};$('saveDraft').onclick=()=>save('draft');$('saveRecipe').onclick=()=>save('active');$('oraNew').onclick=()=>{if(!dirty||confirm('Kaydedilmemiş değişiklikler silinsin mi?'))fresh()};$('oraBack').onclick=()=>{if(saving){notify('Kayıt işleminin tamamlanmasını bekleyin.');return}if(dirty&&!confirm('Kaydedilmemiş değişiklikler var. Çıkılsın mı?'))return;location.href='/benim-okyanusum'};fresh();loadList().catch(error=>{$('recipeList').textContent=error.message||'Reçeteler yüklenemedi.'});addEventListener('beforeunload',event=>{if(dirty||saving){event.preventDefault();event.returnValue=''}});
    })();</script></body></html>`}

    function cleanEasyRecipe(input){
     if(!input||typeof input!=="object"||Array.isArray(input))return null;
     const text=(v,n)=>String(v||"").trim().slice(0,n),num=v=>{const n=Number(v);return Number.isFinite(n)?n:NaN};
     const title=text(input.title,160),category=text(input.category,80),servings=num(input.servings);
     if(!title||!Number.isFinite(servings)||servings<=0||servings>100000)return null;
     const source=Array.isArray(input.ingredients)?input.ingredients:[];if(!source.length||source.length>100)return null;
     const ingredients=[];for(const x of source){if(!x||typeof x!=="object")return null;const name=text(x.name,120),quantity=num(x.quantity),unit=text(x.unit,12),unitCost=num(x.unitCost);if(!name&&quantity===0&&unitCost===0)continue;if(!name||!Number.isFinite(quantity)||quantity<0||quantity>1e7||!Number.isFinite(unitCost)||unitCost<0||unitCost>1e9||!["g","kg","ml","lt","adet"].includes(unit))return null;ingredients.push({name,quantity,unit,unitCost})}
     if(!ingredients.length)return null;
     const steps=(Array.isArray(input.steps)?input.steps:[]).slice(0,30).map(x=>text(x,500)).filter(Boolean);
     const variation=!!input.variation,variationName=text(input.variationName,80),status=input.status==="active"?"active":"draft";
     const out={title,category,servings,variation,variationName,ingredients,steps,status};const packed=JSON.stringify(out);if(new TextEncoder().encode(packed).byteLength>65536||/data:|base64,/i.test(packed))return null;return out;
    }
