    async function memberCostAPI(request,env){try{if(!memberSameOrigin(request))return memberJSON({ok:false,error:"ORIGIN_REJECTED"},403);if(request.method==="POST"&&!request.headers.get("origin"))return memberJSON({ok:false,error:"ORIGIN_REQUIRED"},403);const me=await memberSession(request,env);if(!me)return memberJSON({ok:false,error:"UNAUTHENTICATED",message:"Sunucu kaydı için Benim Okyanus’um hesabına giriş yapın."},401);const expectedBusiness=request.headers.get("x-okyanus-business");if(!expectedBusiness)return memberJSON({ok:false,error:"BUSINESS_SCOPE_REQUIRED",message:"İşletme sayfasını yeniden açın."},400);if(expectedBusiness&&expectedBusiness!==me.business_id)return memberJSON({ok:false,error:"BUSINESS_SESSION_CHANGED",message:"İşletme oturumu değişti. Bu sayfayı yeniden açın."},409);if(request.method==="GET"){const r=await memberD1All(env.DB.prepare(`SELECT id,record_type,title,payload,created_at,updated_at FROM member_cost_records_v3 WHERE business_id=? ORDER BY created_at DESC LIMIT 500`).bind(me.business_id));return memberJSON({ok:true,records:r.results||[]})}if(request.method==="POST"){if(!["owner","admin","editor"].includes(String(me.role||"").toLowerCase()))return memberJSON({ok:false,error:"FORBIDDEN"},403);const declared=Number(request.headers.get("content-length")||0);if(declared>200000)return memberJSON({ok:false,error:"PAYLOAD_TOO_LARGE"},413);let body=/** @type {Record<string,any>} */ ({}),raw="";try{raw=await request.text();if(new TextEncoder().encode(raw).byteLength>200000)return memberJSON({ok:false,error:"PAYLOAD_TOO_LARGE"},413);body=JSON.parse(raw||"{}");if(!body||typeof body!=="object"||Array.isArray(body))return memberJSON({ok:false,error:"INVALID_JSON"},400) }catch{return memberJSON({ok:false,error:"INVALID_JSON"},400)}const payload=JSON.stringify(body);if(new TextEncoder().encode(payload).byteLength>200000)return memberJSON({ok:false,error:"PAYLOAD_TOO_LARGE"},413);const id=memberId("cost"),now=memberNow(),recordType=String(body.record_type||"cost").slice(0,50),title=String(body.title||"COST Kaydı").slice(0,180);await memberD1Run(env.DB.prepare(`INSERT INTO member_cost_records_v3(id,business_id,user_id,record_type,title,payload,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)`).bind(id,me.business_id,me.user_id,recordType,title,payload,now,now));return memberJSON({ok:true,id,createdAt:now},201)}return memberJSON({ok:false,error:"METHOD_NOT_ALLOWED"},405)}catch(error){if(String(error&&error.message||error).startsWith("MEMBER_D1_"))return memberJSON({ok:false,error:"MEMBER_STORAGE_FAILED",message:"Kayıt sistemi işlemi tamamlayamadı. Tekrar deneyin."},503);throw error}}
    function memberLoginPage(me=null,portalEnabled=true){return `<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Üye Giriş | Okyanus EDT</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial;background:#f3f7fa;color:#10283a}.top{background:#061831;color:#fff;padding:14px 18px;display:flex;justify-content:space-between;gap:10px}.top a{color:#fff}.wrap{width:min(1040px,calc(100% - 28px));margin:auto;padding:24px 0}.hero,.card{background:#fff;border:1px solid #d7e4ec;border-radius:16px;padding:22px}.hero{background:linear-gradient(135deg,#061831,#0b4c78);color:#fff;margin-bottom:14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.card form{display:grid;gap:9px}.card input{width:100%;min-height:46px;border:1px solid #c9dbe6;border-radius:9px;padding:11px;font-size:16px}.btn{min-height:46px;border:0;border-radius:9px;background:#087fc1;color:#fff;font-weight:900;padding:10px}.grid>*,.card,.card form{min-width:0}.hero h1,.note,.status{overflow-wrap:anywhere}.hero h1{font-size:clamp(26px,5vw,38px);line-height:1.15}.note{font-size:13px;color:#60798b}.status{font-weight:800;overflow-wrap:anywhere}@media(max-width:700px){.wrap{width:100%;max-width:100%;padding:10px;overflow-x:clip}.grid{grid-template-columns:1fr}.hero,.card{min-width:0;padding:15px}.top{flex-wrap:wrap;align-items:center}.top b,.top a{min-width:0;overflow-wrap:anywhere}}.memberNotice{background:#fff;border:1px solid #bfd5e4;border-left:5px solid #087fc1;border-radius:16px;padding:clamp(16px,3vw,26px);margin:18px 0;line-height:1.65;overflow-wrap:anywhere}.noticeTag{color:#0866a3;font-size:12px;font-weight:900;letter-spacing:.04em}.memberNotice h2{font-size:clamp(22px,4vw,30px);line-height:1.25}.memberNotice h3{font-size:18px;margin:22px 0 8px}.memberNotice a{color:#07639d}.noticeRead{display:flex;align-items:center;gap:12px;padding:14px;background:#eef7fc;border-radius:10px;font-weight:800}.noticeRead input{width:24px;height:24px;flex:0 0 24px}.noticeReopen{min-height:44px;padding:10px 15px;margin:12px 0;border:1px solid #087fc1;border-radius:10px;background:#fff;color:#075185;font-weight:800}.memberNotice[hidden],#authForms[hidden],.noticeReopen[hidden]{display:none!important}#noticeStatus{min-height:24px;font-weight:800}.noticeRead input:focus-visible,.noticeReopen:focus-visible{outline:3px solid #00a7ed;outline-offset:3px}</style></head><body><header class="top"><b>BENİM OKYANUS'UM</b><a href="/">← Ana Sayfa</a></header><main class="wrap"><section class="hero"><small>İŞLETMENİZE ÖZEL ÇALIŞMA ALANI</small><h1>Hesabınıza giriş yapın veya işletmenizi kaydedin.</h1><p>Ürün Seç, COST Radar ve Fotoğrafla Teklif herkese açıktır. Diğer iş araçları işletme hesabınıza özeldir.</p></section>${memberPrivacyNoticeHTML()}${me?'<section class="card"><h2>Oturumunuz açık</h2><p>Bilgilendirme mevcut üyeler için de sunulur.</p><a class="btn" href="/benim-okyanusum">İşletme panelime devam et</a></section>':''}${!portalEnabled?'<p class="note" role="status">Üyelik hizmeti şu anda kullanılamıyor. Açık satış araçlarını kullanabilirsiniz.</p>':''}<section class="grid" id="authForms" ${me?'hidden':''}><article class="card"><h2>Giriş</h2><form id="login"><input name="email" type="email" placeholder="E-posta" autocomplete="email" required><input name="password" type="password" placeholder="6 haneli PIN" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="current-password" required><button class="btn">Giriş Yap</button><div class="status"></div></form></article><article class="card"><h2>İşletme hesabı oluştur</h2><form id="register"><input name="firstName" placeholder="Ad" autocomplete="given-name" required><input name="lastName" placeholder="Soyad" autocomplete="family-name" required><input name="business" placeholder="İşletme adı" autocomplete="organization" required><input name="phone" placeholder="Telefon" autocomplete="tel"><input name="email" type="email" placeholder="E-posta" autocomplete="email" required><input name="password" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" placeholder="6 haneli sayısal PIN" autocomplete="new-password" required><label class="note"><input name="consent" type="checkbox" style="width:auto;min-height:auto"> <a href="/kvkk" target="_blank">KVKK Aydınlatma Metni</a>'ni okudum.</label><label class="note"><input name="terms" type="checkbox" required style="width:auto;min-height:auto"> <a href="/uyelik-bildirgesi" target="_blank" rel="noopener">Üyelik Bildirgesi ve Kullanım Koşulları</a>'nı okudum ve kabul ediyorum.</label><button class="btn">Hesap Oluştur</button><div class="status"></div></form></article></section><p class="note">Eski “Hızlı Form Bilgileri” bu hesaba otomatik aktarılmaz. Paylaşılan cihazlarda yerel form kaydını ayrıca temizleyebilirsiniz.</p></main><script>(function(){const box=document.getElementById('noticeRead'),notice=document.getElementById('memberNotice'),status=document.getElementById('noticeStatus'),reopen=document.getElementById('noticeReopen');let busy=false;box.addEventListener('change',async()=>{if(!box.checked||busy)return;busy=true;box.disabled=true;status.textContent='Okuma kaydı saklanıyor…';try{const r=await fetch('/api/member/notice-ack',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({read:true,version:'${memberNoticeVersion()}'})}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.message||'Okuma kaydı saklanamadı.');notice.hidden=true;reopen.hidden=false;reopen.focus()}catch(e){box.checked=false;status.textContent=e.message||'Okuma kaydı saklanamadı; bilgilendirme açık kaldı.'}finally{busy=false;box.disabled=false}});reopen.addEventListener('click',()=>{notice.hidden=false;reopen.hidden=true;box.checked=false;status.textContent='';document.getElementById('noticeTitle').setAttribute('tabindex','-1');document.getElementById('noticeTitle').focus()});})();${!portalEnabled?"document.querySelectorAll('#authForms input,#authForms button').forEach(x=>x.disabled=true);":""}for(const f of document.querySelectorAll('form'))f.addEventListener('submit',async e=>{e.preventDefault();const b=e.submitter,s=f.querySelector('.status');b.disabled=true;s.textContent='İşleniyor...';const x=Object.fromEntries(new FormData(f));x.consent=!!f.elements.consent?.checked;x.terms=!!f.elements.terms?.checked;try{const r=await fetch('/api/member/'+f.id,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(x)}),j=await r.json();s.textContent=j.message||j.error||'Tamamlandı';if(r.ok&&j.redirect){if(f.id==='login'){try{const channel=new BroadcastChannel('oky-member-session-v1');channel.postMessage('changed');channel.close()}catch(_){}try{localStorage.setItem('oky:member-session-event:v1',String(Date.now())+':'+Math.random())}catch(_){}}const n=new URLSearchParams(location.search).get('next');location.href=n&&n.startsWith('/')&&!n.startsWith('//')?n:j.redirect}}catch(_){s.textContent='Bağlantı hatası.'}finally{b.disabled=false}});if(new URLSearchParams(location.search).get('verified'))document.querySelector('#login .status').textContent='E-posta doğrulandı. Giriş yapabilirsiniz.';</script></body></html>`}
    function memberWorkspacePageLegacy(me){return `<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Benim Okyanus’um</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial;background:#f3f7fa;color:#10283a}.top{background:#061831;color:#fff;padding:14px 18px;display:flex;justify-content:space-between;gap:10px}.wrap{width:min(1400px,calc(100% - 28px));margin:auto;padding:22px 0}.hero{background:linear-gradient(135deg,#061831,#0b4c78);color:#fff;border-radius:18px;padding:24px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:14px}.card{background:#fff;border:1px solid #d7e4ec;border-radius:14px;padding:18px}.card a{display:inline-block;margin-top:8px;color:#087fc1;font-weight:900}.logout{border:1px solid #ffffff55;background:transparent;color:#fff;border-radius:8px;padding:9px;font-weight:900}@media(max-width:760px){.wrap{width:100%;padding:10px}.grid{grid-template-columns:1fr}.top{flex-wrap:wrap}.hero,.card{padding:15px}}</style></head><body><header class="top"><b>BENİM OKYANUS'UM</b><button class="logout" id="logout">Çıkış</button></header><main class="wrap"><section class="hero"><small>${escapeHTML(me.business_display_name||me.business_name)}</small><h1>Hoş geldiniz, ${escapeHTML(me.first_name)}.</h1><p>İşletmenize ait araçlara güvenli oturum üzerinden erişiyorsunuz.</p></section><section class="grid"><article class="card"><h2>Dijital Menü</h2><p>Menünüzü oluşturun ve mevcut QR menünüzü yönetin.</p><a href="/dijital-menu">Dijital Menüye Git →</a></article><article class="card"><h2>COST Merkezi</h2><p>Hesap araçlarını kullanın. Hesaba özel kayıtlar ayrı güvenlik aşamasında etkinleştirilecektir.</p><a href="/cost">COST'u Aç →</a></article><article class="card"><h2>Akademi</h2><p>İşletme eğitimlerine ve araçlarına ulaşın.</p><a href="/akademi">Akademiye Git →</a></article></section></main><script>logout.onclick=async()=>{await fetch('/api/member/logout',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});location.href='/uye'};</script></body></html>`}

    function privacyPage(){
     return corporateShell("Gizlilik Politikası","GİZLİLİK",`<section class="hero"><small>GİZLİLİK & KİŞİSEL VERİLER</small><h1>Veriyi gerektiği kadar, amacı için kullanırız.</h1><p>Bu sayfa Okyanus EDT web sitesi, teklif ve iletişim alanlarında işlenen bilgiler hakkında genel gizlilik yaklaşımını açıklar. KVKK aydınlatması ile açık rıza birbirinden ayrı kavramlardır.</p></section>
    <section class="grid"><article class="card wide"><h2>Gizlilik Yaklaşımımız</h2><p>Okyanus EDT, kişisel verilerin işlenmesinde amaçla sınırlılık, veri minimizasyonu ve güvenli işlem ilkelerini esas alır. Teklif veya iletişim için verilen bilgiler, ilgili talebin alınması, değerlendirilmesi, iletişim kurulması ve sonuçlandırılması amacıyla kullanılır.</p></article>
    <article class="card"><h3>İşlenebilen Bilgiler</h3><p>İşleme göre ad, soyad, işletme/restoran adı, telefon, e-posta, seçilen ürünler ve kullanıcı tarafından iletişim alanına yazılan mesaj bilgileri işlenebilir.</p></article>
    <article class="card"><h3>Kullanım Amaçları</h3><p>Teklif talebini yönetmek, kullanıcıyla iletişim kurmak, ürün ve tedarik talebini değerlendirmek, talebi sonuçlandırmak ve web hizmetlerinin güvenli çalışmasını sağlamak.</p></article>
    <article class="card"><h3>Çerez ve Tercihler</h3><p>Geçmişte belirlenen mimaride çerezler zorunlu, işlevsel, analitik ve pazarlama kategorilerine ayrılmış; zorunlu olmayan kategoriler varsayılan kapalı olacak şekilde tasarlanmıştır. V2'ye üçüncü taraf analitik veya pazarlama servisi eklenirse ilgili tercih mekanizması etkinleştirilmeden çalıştırılmamalıdır.</p></article>
    <article class="card"><h3>Pazarlama İzni</h3><p>Teklif veya iletişim amacıyla yapılan KVKK bilgilendirmesi, tek başına pazarlama ya da ticari elektronik ileti izni anlamına gelmez. Böyle bir kullanım gerektiğinde ayrı ve açık bir tercih mekanizması kullanılmalıdır.</p></article>
    <article class="card"><h3>Veri Sorumlusu / KVKK İletişimi</h3><p><b>OKYANUS EDT – Orhan Güngör</b><br>Oruçreis Mahallesi, 600. Sokak, No: 21, İç Kapı No: 4, Esenler / İstanbul<br>Telefon: 0535 881 32 64<br>E-posta / KVKK iletişim: <a href="mailto:info@okyonusedt.com">info@okyonusedt.com</a></p></article>
    <article class="card"><h3>KVKK Kapsamındaki Haklar</h3><p>İlgili kişiler 6698 sayılı KVKK'nın 11. maddesi kapsamındaki hakları için yukarıdaki kurumsal iletişim kanalından Okyanus EDT'ye başvurabilir.</p></article>
    <article class="card wide"><h3>Güvenlik ve Üçüncü Taraflar</h3><p>Kişisel veriler gereksiz alanlarda yayınlanmamalı, kişisel e-posta hesapları yerine kurumsal iletişim kanalları kullanılmalıdır. Gelecekte üçüncü taraf hizmetleri eklendiğinde sağlayıcı, amaç ve kullanılan çerez/veri işleme unsurları politika metnine eklenmeli ve gerekli kullanıcı tercihleri alınmalıdır.</p><div class="note"><b>Teknik uyum notu:</b> Bu sayfa geçmişte doğrulanmış Okyanus EDT KVKK/gizlilik mimarisinin V2'ye aktarımıdır. Mevzuata özgü nihai hukuki değerlendirme yerine geçmez.</div></article></section>`)}
    function kvkkPage(){
     return corporateShell("KVKK Aydınlatma Metni","KVKK",`<section class="hero"><small>6698 SAYILI KİŞİSEL VERİLERİN KORUNMASI KANUNU</small><h1>KVKK Aydınlatma Metni</h1><p>Okyanus EDT teklif, iletişim, işletme üyeliği ve özel sayfa giriş günlüğü süreçlerine ilişkin bilgilendirme.</p></section><section class="grid"><article class="card wide"><h2>Veri Sorumlusu</h2><p><b>OKYANUS EDT – Orhan Güngör</b><br>Oruçreis Mahallesi, 600. Sokak, No: 21, İç Kapı No: 4, Esenler / İstanbul<br>Telefon: 0535 881 32 64<br>KVKK iletişim: <a href="mailto:info@okyonusedt.com">info@okyonusedt.com</a></p></article><article class="card"><h3>İşlenen Veriler</h3><p>İlgili işleme göre ad, soyad, işletme adı, telefon, e-posta, seçilen ürünler ve iletişim mesajı.</p></article><article class="card"><h3>İşleme Amacı</h3><p>Teklif veya iletişim talebinin alınması, değerlendirilmesi, kullanıcıyla iletişim kurulması ve talebin sonuçlandırılması.</p></article><article class="card wide"><h3>Üyelik ve özel sayfa giriş günlüğü</h3><p>İşletme üyeliğinde ad, soyad, işletme, e-posta, isteğe bağlı telefon, güvenli parola doğrulama bilgileri ve hesaba bağlı çalışma kayıtları; özel sayfa giriş günlüğünde zaman, sayfa yolu, rastgele ziyaret kodu özeti ve varsa hesap kimliği işlenir. Ham IP ve çalışma içeriği bu özel günlüğe yazılmaz. Özel sayfa giriş/okuma günlükleri 40 gün sonra geçerliliğini yitirir ve otomatik temizlikte silinir; çalışma kayıtları ve sözleşme kabul kanıtları bu günlükten ayrıdır.</p><p>Üyelik işlemleri sözleşme kurulması/ifası (m.5/2-c), güvenlik günlükleri gerekli ve ölçülü meşru menfaat (m.5/2-f), yasal yükümlülük ve hak talepleri ilgili durumlarda (m.5/2-ç/e) kapsamında değerlendirilir. Veriler hizmetin sunulması için gerekli barındırma/e-posta sağlayıcıları ve kanunen yetkili mercilerle gerekli ölçüde işlenebilir. Cloudflare bulut altyapısı kullanılır; yurt dışı aktarım halinde m.9 güvencelerinin sağlanması gerekir. Ayrıntılı işletme bilgilendirmesi <a href="/uyelik-bildirgesi">Üyelik Bildirgesi</a> içinde sunulur.</p></article><article class="card wide"><h3>Temel İlkeler ve Haklar</h3><p>Kişisel veriler 6698 sayılı KVKK kapsamındaki veri işleme şartları ile amaçla sınırlılık ve veri minimizasyonu ilkeleri gözetilerek işlenir. İlgili kişiler KVKK m.11 kapsamındaki haklarını kurumsal KVKK iletişim kanalı üzerinden kullanabilir. Aydınlatma metni, pazarlama veya ticari elektronik ileti izni değildir.</p></article></section>`)}

