    function mailConfig(env){return{to:String(env&&env.MAIL_TO||"hasan.kaya474@gmail.com").trim(),from:String(env&&env.MAIL_FROM||"teklif@okyonusedt.com").trim()}}
    function safeMailHeader(value){return String(value||"").replace(/[\r\n]+/g," ").trim()}
    async function sendBoundEmail(env, message){
      if(!env||!env.EMAIL||typeof env.EMAIL.send!=="function")return null;
      const cfg=mailConfig(env); if(!cfg.to||!cfg.from)throw new Error("EMAIL_ADDRESS_NOT_CONFIGURED");
      const from=safeMailHeader(cfg.from),to=safeMailHeader(message.to||env.ADMIN_MAIL_TO||cfg.to),replyTo=safeMailHeader(message.replyTo);
      if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(from)||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(replyTo))throw new Error("EMAIL_ADDRESS_NOT_CONFIGURED");
      const result=await env.EMAIL.send({to,from,replyTo,subject:safeMailHeader(message.subject).slice(0,180),text:String(message.text||""),html:String(message.html||"")});
      return result||{messageId:null};
    }

    async function contactAPI(request, env) {
      let body; try{body=await request.json()}catch{return responseJSON({ok:false,error:"INVALID_JSON",message:"İletişim verisi okunamadı."},400)}
      const name=String(body&&body.name||"").trim(),business=String(body&&body.business||"").trim(),phone=String(body&&body.phone||"").trim(),email=String(body&&body.email||"").trim(),subject=String(body&&body.subject||"Genel Bilgi").trim(),message=String(body&&body.message||"").trim();
      if(!name||!phone||!email||!message||body.consent!==true)return responseJSON({ok:false,error:"MISSING_FIELDS",message:"Zorunlu bilgiler veya iletişim onayı eksik."},400);
      const phoneDigits=phone.replace(/\D/g,"");if(name.length>120||business.length>160||phone.length>30||email.length>160||subject.length>120||message.length>5000)return responseJSON({ok:false,error:"FIELD_TOO_LONG",message:"Alan uzunluklarını kontrol edin."},400);if(!/^\+?[0-9 ()-]+$/.test(phone)||phoneDigits.length<10||phoneDigits.length>15)return responseJSON({ok:false,error:"INVALID_PHONE",message:"Geçerli bir telefon numarası girin."},400);if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email))return responseJSON({ok:false,error:"INVALID_EMAIL",message:"Geçerli bir e-posta adresi girin."},400);
      if(env&&env.EMAIL&&typeof env.EMAIL.send==="function"){
        try{const text=`Okyanus EDT iletişim formu\n\nAd: ${name.slice(0,120)}\nİşletme: ${business.slice(0,160)}\nTelefon: ${phone.slice(0,30)}\nE-posta: ${email.slice(0,160)}\nKonu: ${subject.slice(0,120)}\n\nMesaj:\n${message.slice(0,5000)}`;await sendBoundEmail(env,{replyTo:email.slice(0,160),subject:`Okyanus EDT iletişim · ${subject.slice(0,90)}`,text,html:`<h2>Okyanus EDT iletişim formu</h2><p><b>Ad:</b> ${escapeHTML(name.slice(0,120))}<br><b>İşletme:</b> ${escapeHTML(business.slice(0,160))}<br><b>Telefon:</b> ${escapeHTML(phone.slice(0,30))}<br><b>E-posta:</b> ${escapeHTML(email.slice(0,160))}<br><b>Konu:</b> ${escapeHTML(subject.slice(0,120))}</p><p>${escapeHTML(message.slice(0,5000)).replace(/\n/g,"<br>")}</p>`});return responseJSON({ok:true,message:"Mesajınız başarıyla e-posta ile iletildi.",delivery:"CLOUDFLARE_EMAIL"})}catch(e){return responseJSON({ok:false,error:"CONTACT_EMAIL_FAILED",message:"Mesaj e-posta servisine ulaştırılamadı."},502)}
      }
      const webhook=String(env&&env.CONTACT_WEBHOOK_URL||env&&env.QUOTE_WEBHOOK_URL||"").trim(); if(!webhook)return responseJSON({ok:false,error:"CONTACT_NOT_CONFIGURED",message:"İletişim gönderimi için EMAIL binding veya webhook henüz yapılandırılmadı."},503);
      try{const payload={source:"OKYANUS_EDT_V2_CONTACT",customer:{name,business,phone,email},subject,message,createdAt:new Date().toISOString()},headers=/** @type {Record<string,string>} */ ({"content-type":"application/json"});if(env&&env.BRIDGE_SECRET)headers["x-bridge-secret"]=String(env.BRIDGE_SECRET);const upstream=await fetch(webhook,{method:"POST",headers,body:JSON.stringify(payload)});let result=/** @type {Record<string,any>} */ ({});try{result=await upstream.json()}catch{}if(!upstream.ok||result.ok===false)return responseJSON({ok:false,error:"CONTACT_UPSTREAM_FAILED",message:"Mesaj iletişim servisine ulaştırılamadı."},502);return responseJSON({ok:true,message:"Mesajınız başarıyla iletildi.",messageNo:result.messageNo||result.quoteNo||null})}catch(e){return responseJSON({ok:false,error:"CONTACT_NETWORK_ERROR",message:"İletişim servisinde bağlantı hatası oluştu."},502)}
    }

    const SEAFOOD_B2B_QUOTE_CATALOG=Object.freeze([{"id":"sea-01","name":"Gigas Kalamar Tüp U5 %10 Glaze","category":"Kalamar","unit":"Kg"},{"id":"sea-02","name":"Gigas Kalamar Tüp U5 %30 Glaze","category":"Kalamar","unit":"Kg"},{"id":"sea-03","name":"Halka Kalamar %30 Glaze","category":"Kalamar","unit":"Kg"},{"id":"sea-04","name":"Loligo Kalamar AA U3","category":"Kalamar","unit":"Kg"},{"id":"sea-05","name":"Loligo Kalamar AA 3/6","category":"Kalamar","unit":"Kg"},{"id":"sea-06","name":"Loligo Kalamar AA U2","category":"Kalamar","unit":"Kg"},{"id":"sea-07","name":"Bütün Temiz Kalamar U5","category":"Kalamar","unit":"Kg"},{"id":"sea-08","name":"Bütün Temiz Kalamar U10","category":"Kalamar","unit":"Kg"},{"id":"sea-09","name":"Bütün Temiz Kalamar 10/20","category":"Kalamar","unit":"Kg"},{"id":"sea-10","name":"Et Karides 16/20 Kuyruklu %10 Glaze","category":"Karides","unit":"Kg"},{"id":"sea-11","name":"Et Karides 21/25 %10 Glaze","category":"Karides","unit":"Kg"},{"id":"sea-12","name":"Et Karides 31/40 %10 Glaze","category":"Karides","unit":"Kg"},{"id":"sea-13","name":"Et Karides 41/50 %10 Glaze","category":"Karides","unit":"Kg"},{"id":"sea-14","name":"Et Karides 16/20 %30 Glaze","category":"Karides","unit":"Kg"},{"id":"sea-15","name":"Et Karides 21/25 %30 Glaze","category":"Karides","unit":"Kg"},{"id":"sea-16","name":"Et Karides 31/40 %30 Glaze","category":"Karides","unit":"Kg"},{"id":"sea-17","name":"Et Karides 41/50 %30 Glaze","category":"Karides","unit":"Kg"},{"id":"sea-18","name":"Et Karides 51/60 %30 Glaze","category":"Karides","unit":"Kg"},{"id":"sea-19","name":"Black Tiger Karides 8/12","category":"Black Tiger","unit":"Kg"},{"id":"sea-20","name":"Black Tiger Karides 16/20","category":"Black Tiger","unit":"Kg"},{"id":"sea-21","name":"Pangasius Fileto 4'lü %10 Glaze","category":"Balık","unit":"Kg"},{"id":"sea-22","name":"Unagi 13-15 oz","category":"Unagi","unit":"Kg"},{"id":"sea-23","name":"Ahtapot 2/3","category":"Ahtapot","unit":"Kg"},{"id":"sea-24","name":"Ahtapot 3/5","category":"Ahtapot","unit":"Kg"}]);
    async function quoteAPI(request, env) {

      let body;

      const contentType=String(request.headers.get("content-type")||"").toLowerCase();
      const contentLength=Number(request.headers.get("content-length")||0);
      if(!contentType.includes("application/json"))return responseJSON({ok:false,error:"UNSUPPORTED_MEDIA_TYPE",message:"Teklif verisi JSON biçiminde gönderilmelidir."},415);
      if(contentLength>100000)return responseJSON({ok:false,error:"PAYLOAD_TOO_LARGE",message:"Teklif verisi izin verilen boyutu aşıyor."},413);

      try {
        body = await request.json();
      } catch {
        return responseJSON(
          {
            ok: false,
            error: "INVALID_JSON",
            message: "Teklif verisi okunamadı."
          },
          400
        );
      }

      const customer = body && body.customer ? body.customer : {name:[body&&body.firstName,body&&body.lastName].filter(Boolean).join(" "),business:body&&body.businessName,phone:body&&body.phone,email:body&&body.email};

      const products =
        body && Array.isArray(body.products)
          ? body.products
          : [];
      if (!products.length) return responseJSON({ok:false,error:"EMPTY_QUOTE",message:"Teklif listesinde ürün bulunmuyor."},400);

      const name =
        String(customer.name || "").trim();

      const business =
        String(customer.business || "").trim();

      const phone =
        String(customer.phone || "").trim();

      const email =
        String(customer.email || "").trim();

      if (
        !name ||
        !business ||
        !phone ||
        !email
      ) {
        return responseJSON(
          {
            ok: false,
            error: "MISSING_FIELDS",
            message: "Zorunlu bilgiler eksik."
          },
          400
        );
      }

      const consentOk=body&&((body.consent&&body.consent.kvkk===true)||body.kvkkAcknowledged===true);
      if(!consentOk)return responseJSON({ok:false,error:"KVKK_ACK_REQUIRED",message:"KVKK Aydınlatma Metni bilgilendirmesi onaylanmalıdır."},400);
      const phoneDigits=phone.replace(/\D/g,"");
      if(name.length<3||name.length>120||business.length<2||business.length>160||phone.length>30||email.length>160)return responseJSON({ok:false,error:"INVALID_FIELDS",message:"Ad, işletme ve iletişim alanlarının uzunluklarını kontrol edin."},400);
      if(!/^\+?[0-9 ()-]+$/.test(phone)||phoneDigits.length<10||phoneDigits.length>15)return responseJSON({ok:false,error:"INVALID_PHONE",message:"Geçerli bir telefon numarası girin."},400);
      if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email))return responseJSON({ok:false,error:"INVALID_EMAIL",message:"Geçerli bir e-posta adresi girin."},400);
      if(products.length>100)return responseJSON({ok:false,error:"TOO_MANY_PRODUCTS",message:"Tek seferde en fazla 100 ürün gönderilebilir."},400);
      const knownProducts=new Map([...ACTIVE_PRODUCT_CATALOG,...SEAFOOD_B2B_QUOTE_CATALOG].map(x=>[String(x.id),x]));
      const allowedUnits=new Set(["Adet","Paket","Koli","Kg","Gram","Litre","Teneke","Kova","Kutu","Şişe","Kasa"]);
      const safeProducts=products.filter(x=>x&&knownProducts.has(String(x.id||""))).slice(0,100).map(x=>{const canonical=knownProducts.get(String(x.id)),quantity=Number(x.quantity),unit=String(x.unit||"").trim();return{id:String(canonical.id),name:String(canonical.name).slice(0,180),quantity:Number.isFinite(quantity)&&quantity>0&&quantity<=100000?Math.round(quantity*100)/100:null,unit:allowedUnits.has(unit)?unit:null}});
      if(!safeProducts.length)return responseJSON({ok:false,error:"INVALID_PRODUCTS",message:"Geçerli ürün bulunamadı."},400);
      if(safeProducts.some(x=>x.quantity===null||!Number.isFinite(x.quantity)||x.quantity<=0||x.unit===null))return responseJSON({ok:false,error:"INVALID_QUANTITY_UNIT",message:"Her ürün için geçerli miktar ve birim seçilmelidir."},400);

      const quoteNo=`OKY-${new Date().toISOString().slice(0,10).replace(/-/g,"")}-${crypto.randomUUID().slice(0,8).toUpperCase()}`;
      const payload = {source:"OKYANUS_EDT_V2",quoteNo,customer:{name:name.slice(0,120),business:business.slice(0,160),phone:phone.slice(0,30),email:email.slice(0,160)},products:safeProducts,consent:{kvkk:true,textVersion:String(body&&body.consent&&body.consent.textVersion||"2026-09-08-v1").slice(0,40),purpose:"QUOTE_REQUEST",acceptedAt:new Date().toISOString()},createdAt:new Date().toISOString()};
      const quoteMessage='Talep No: '+quoteNo+'\n\nSeçilen ürünler ve miktarlar:\n'+safeProducts.map((p,i)=>`${i+1}. ${p.name} — ${p.quantity} ${p.unit} [${p.id}]`).join('\n')+(body.note?'\n\nMüşteri notu: '+String(body.note).slice(0,1000):'');
      const savedResponse=await okyContactMessageAPI(new Request(request.url,{method:'POST',headers:request.headers,body:JSON.stringify({name,business,phone,email,subject:'Teklif talebi · '+quoteNo,message:quoteMessage,consent:true})}),env);
      const savedResult=await savedResponse.json();
      if(!savedResponse.ok||!savedResult.ok)return responseJSON(savedResult,savedResponse.status);
      return responseJSON({ok:true,quoteNo,id:savedResult.id,message:'Teklif talebiniz kaydedildi.',delivery:'D1_SAVED',notification:savedResult.notification},201);
    }

    async function costPersistenceAPI(request, env) {
      if (!env || !env.DB) {
        return responseJSON({
          ok: false,
          error: "D1_NOT_BOUND",
          message: "COST D1 bağlantısı bulunamadı; mevcut cihaz kayıtları korunuyor."
        }, 503);
      }

      const db = env.DB;

      if (request.method === "GET") {
        const r = await db.prepare(
          "SELECT id, record_type, title, payload, created_at, updated_at FROM cost_records ORDER BY created_at DESC LIMIT 500"
        ).all();

        return responseJSON({
          ok: true,
          records: r.results || []
        });
      }

      if (request.method === "POST") {
        let body;

        try {
          body = await request.json();
        } catch {
          return responseJSON({
            ok: false,
            error: "INVALID_JSON"
          }, 400);
        }

        const id = crypto.randomUUID();
        const createdAt = new Date().toISOString();
        const recordType = body?.record_type || "cost";
        const title = body?.title || "COST Kaydı";

        await db.prepare(
          "INSERT INTO cost_records (id, record_type, title, payload, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?)"
        )
        .bind(
          id,
          recordType,
          title,
          JSON.stringify(body || {}),
          createdAt,
          createdAt
        )
        .run();

        return responseJSON({
          ok: true,
          id,
          createdAt
        }, 201);
      }

      return responseJSON({
        ok: false,
        error: "METHOD_NOT_ALLOWED"
      }, 405);
    }



