      return corporateShell(g?g.title+' Kılavuzu':'Yardım Merkezi','YARDIM / KILAVUZ',`${detail}<style>.guidePicker{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.guideCard{display:flex;flex-direction:column;gap:10px;background:#fff;border:1px solid #d4e2ec;border-radius:16px;padding:20px;color:#0a2943;text-decoration:none;min-height:190px;box-shadow:0 8px 24px #06294710}.guideCard:hover,.guideCard:focus-visible{border-color:#0788cf;transform:translateY(-2px)}.guideCard b{font-size:20px}.guideCard span{line-height:1.55;color:#526b7d;flex:1}.guideCard strong{color:#087fc1}.guideDetail{max-width:960px;margin:auto}.backGuide{display:inline-block;margin-bottom:18px;color:#086fae;font-weight:800}.guideDetail>small{display:block;color:#087fc1;font-weight:900}.guideDetail h1{font-size:42px;margin:7px 0}.lead{font-size:18px;line-height:1.65}.flowGuide{background:#061831;color:#fff;border-radius:13px;padding:16px;margin:20px 0}.guideRows{display:grid;gap:12px}.guideRow{display:grid;grid-template-columns:48px 1fr;gap:14px;background:#fff;border:1px solid #d5e3ec;border-radius:15px;padding:18px}.stepNo{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:#0788cf;color:#fff;font-weight:900}.guideRow h2{margin:4px 0 13px;font-size:21px}.guideRow dl{margin:0;display:grid;grid-template-columns:175px 1fr;gap:8px 13px}.guideRow dt{font-weight:900;color:#0a3555}.guideRow dd{margin:0;line-height:1.55}.guideEnd{margin-top:18px;background:#eaf7ff;border:1px solid #b8e1f6;border-radius:14px;padding:20px}.guideEnd p{line-height:1.55}@media(max-width:760px){.guidePicker{grid-template-columns:1fr}.guideCard{min-height:0}.guideDetail h1{font-size:31px}.guideRow{grid-template-columns:1fr}.guideRow dl{grid-template-columns:1fr}.guideRow dd{margin-bottom:8px}}</style><script>(function(){if(!new URLSearchParams(location.search).get('modul')&&location.hash){var k=location.hash.slice(1);if(${JSON.stringify(Object.keys(guides))}.includes(k))location.replace('/yardim?modul='+encodeURIComponent(k))}})();</script>`);
