            const draftSaved=dmSaveDraft();preview();
            if(!draftSaved){msg("Menü canlıda, ancak düzenleme anahtarı bu cihazda kaydedilemedi. Sayfayı kapatmadan tarayıcı depolamasını kontrol edip Taslağı Kaydet düğmesine tekrar basın.",true);return}
            msg(updating?"Menü güncellendi. QR kodunuz değişmedi.":"Menü CANLIYA ÇIKTI. QR kodunuz hazır.");
