        style.textContent="@page{size:"+page+";margin:12mm}*{box-sizing:border-box}html,body{margin:0;min-height:100%;print-color-adjust:exact;-webkit-print-color-adjust:exact}body{font-family:Arial;color:#10283a}.dmPreview{min-height:100vh;padding:18px}.dmPrevHead{text-align:center;border-bottom:2px solid #0b4f7c;padding:14px}.dmPrevHead h2{font-size:25px;margin:0}.dmPrevHead h4{margin:6px}.dmPrevLogo{display:block;max-width:90px;max-height:70px;object-fit:contain;margin:0 auto 8px}.dmPrevCat h3{border-bottom:1px solid #bbb;padding-bottom:5px}.dmPrevItem{display:grid;grid-template-columns:70px 1fr auto;gap:10px;padding:8px 0;border-bottom:1px dashed #ccc;break-inside:avoid}.dmPrevItem.noimg{grid-template-columns:1fr auto}.dmPrevItem img{width:70px;height:52px;object-fit:cover;border-radius:6px}.dmPrevItem p{font-size:11px;margin:3px 0}.dmPrevItem strong{white-space:nowrap}.classic{background:#fffdf8}.classic .dmPrevHead{font-family:Georgia,serif;border-color:#7a5638}.classic .dmPrevCat h3{color:#5c402d}.classic .dmPrevItem strong{color:#6b4932}.modern{background:#f4f9fc}.modern .dmPrevHead{background:linear-gradient(135deg,#041d33,#0b5d8d);color:#fff;border:0;border-radius:14px;text-align:left}.modern .dmPrevHead p{color:#d7eaf5}.modern .dmPrevLogo{margin-left:0}.modern .dmPrevItem{background:#fff;border:1px solid #dbe8ef;border-radius:12px;padding:10px;margin:8px 0}.premium{background:#151515;color:#f5f0e4}.premium .dmPrevHead{border-color:#c9a34e}.premium .dmPrevHead p,.premium .dmPrevItem p{color:#bdb6a8}.premium .dmPrevCat h3{color:#e0c276;border-color:#4b4130}.premium .dmPrevItem{border-color:#3b3429}.premium .dmPrevItem strong{color:#e0c276}.cafe{background:#fff7ed}.cafe .dmPrevHead{background:#8a5b3d;color:#fff;border:0;border-radius:18px}.cafe .dmPrevHead p{color:#f5e8dc}.cafe .dmPrevItem{background:#fff;border:1px solid #ead9c9;border-radius:14px;padding:10px;margin:8px 0}.cafe .dmPrevItem strong{color:#8a5533}";
        head.appendChild(style);
        style.textContent+=".bistro{background:#f3efe8}.bistro .dmPrevHead{background:#253b35;color:#fff;border:0;border-radius:12px}.bistro .dmPrevItem strong{color:#735a31}.street{background:#fff6cf}.street .dmPrevHead{background:#171717;color:#ffd52d;border:3px solid #ffd52d}.street .dmPrevItem strong{color:#b9471c}.mediterranean{background:#f5fbfa}.mediterranean .dmPrevHead{background:linear-gradient(135deg,#087b91,#66b8aa);color:#fff;border:0;border-radius:20px}.mediterranean .dmPrevItem strong{color:#087b91}.minimal{background:#fff;color:#111}.minimal .dmPrevHead{text-align:left;border-color:#111}.minimal .dmPrevItem strong{color:#111}";
        body.className=state.theme;
